window.LCE_GLOSSA = Object.assign(window.LCE_GLOSSA || {}, {
  "Jo 1,1-18": "(CENÁRIO: antes da criação → mundo → humanidade)\nNO PRINCÍPIO / PALAVRA EXISTIR / COM DEUS / SER DEUS.\nTUDO POR ELA CRIAR / VIDA E LUZ.\nLUZ BRILHAR ESCURIDÃO / ESCURIDÃO NÃO VENCER.\nJOÃO TESTEMUNHAR LUZ.\nPALAVRA SE FAZER CARNE / MORAR ENTRE NÓS / GLÓRIA REVELAR.\nMOISÉS LEI DAR / JESUS CRISTO GRAÇA E VERDADE TRAZER.",
  "Jo 1,29-34": "(CENÁRIO: JOÃO vê JESUS aproximar)\nJOÃO APONTAR JESUS: CORDEIRO DE DEUS / TIRAR PECADO MUNDO.\nEU ANTES NÃO CONHECER / MAS BATIZAR PARA ELE SER REVELADO.\nESPÍRITO DESCER COMO POMBA / PERMANECER SOBRE ELE.\nEU VER / TESTEMUNHAR: ELE FILHO DE DEUS.",
  "Jo 1,35-42": "(CENÁRIO: JOÃO com dois discípulos; JESUS passando)\nJOÃO APONTAR: CORDEIRO DE DEUS.\nDOIS DISCÍPULOS SEGUIR JESUS.\nJESUS PERGUNTAR: VOCÊS PROCURAR O-QUÊ?\nELES PERGUNTAR ONDE MORAR / JESUS: VENHAM VER.\nANDRÉ ENCONTRAR SIMÃO / DIZER: MESSIAS ENCONTRAMOS.\nJESUS OLHAR SIMÃO / DAR NOVO NOME PEDRO.",
  "Jo 1,6-8.19-28": "JOÃO ENVIADO POR DEUS / TESTEMUNHAR LUZ / ELE PRÓPRIO LUZ NÃO.\nLÍDERES PERGUNTAR: QUEM VOCÊ?\nJOÃO NEGAR SER MESSIAS / ELIAS / PROFETA.\nDIZER: EU VOZ DESERTO / PREPARAR CAMINHO SENHOR.\nEU BATIZAR ÁGUA / ENTRE VOCÊS ALGUÉM JÁ ESTÁ / VOCÊS NÃO CONHECER.",
  "Jo 10,1-10": "(CENÁRIO: curral / porta / pastor / ladrão)\nQUEM ENTRAR PELA PORTA / PASTOR OVELHAS.\nOVELHAS CONHECER VOZ / PASTOR CHAMAR NOME / CONDUZIR.\nESTRANHO ELAS NÃO SEGUIR.\nJESUS: EU PORTA.\nQUEM ENTRAR POR MIM / SALVAR / ENTRAR-SAÍR / PASTO ENCONTRAR.\nLADRÃO ROUBAR-MATAR / EU VIM VIDA DAR / VIDA PLENA.",
  "Jo 10,11-18": "JESUS: EU BOM PASTOR.\nBOM PASTOR VIDA DAR PELAS OVELHAS.\nEMPREGADO VER LOBO / FUGIR / OVELHAS DISPERSAR.\nEU CONHECER MINHAS OVELHAS / ELAS ME CONHECER.\nOUTRAS OVELHAS TAMBÉM TRAZER / UM SÓ REBANHO / UM SÓ PASTOR.\nMINHA VIDA EU ENTREGO LIVREMENTE / E RECEBER DE NOVO.",
  "Jo 10,27-30": "JESUS: MINHAS OVELHAS OUVIR MINHA VOZ.\nEU CONHECER ELAS / ELAS ME SEGUIR.\nEU DAR VIDA ETERNA / NINGUÉM ARRANCAR MINHA MÃO.\nPAI MAIOR QUE TODOS / NINGUÉM ARRANCAR MÃO DELE.\nEU E PAI / UM.",
  "Jo 11,1-45": "(CENÁRIO: BETÂNIA; LÁZARO doente → morto; irmãs Marta e Maria)\nJESUS SABER LÁZARO DOENTE / DEMORAR.\nQUANDO CHEGAR / LÁZARO QUATRO DIAS SEPULTADO.\nMARTA: SE TU ESTIVESSE AQUI / ELE NÃO MORRER.\nJESUS: EU RESSURREIÇÃO E VIDA / QUEM CRER VIVER.\nMARIA E POVO CHORAR / JESUS COMOVER / CHORAR.\nSEPULCRO ABRIR / JESUS ORAR AO PAI / CHAMAR: LÁZARO, SAIR.\nLÁZARO SAIR VIVO / MUITOS CRER.",
  "Jo 12,20-33": "ALGUNS GREGOS PROCURAR JESUS.\nJESUS: HORA CHEGOU / FILHO HOMEM SER GLORIFICADO.\nGRÃO TRIGO SE NÃO MORRER / FICAR SÓ; SE MORRER / FRUTO MUITO.\nQUEM SERVIR MIM / SEGUIR.\nMINHA ALMA PERTURBADA / MAS PARA ESTA HORA EU VIM.\nPAI GLORIFICAR TEU NOME.\nVOZ CÉU RESPONDER.\nJESUS: QUANDO EU FOR LEVANTADO / TODOS ATRAIR.",
  "Jo 13,31-33.34-35": "JUDAS SAIR / JESUS DIZER: AGORA FILHO HOMEM GLORIFICADO.\nNOVO MANDAMENTO EU DAR: VOCÊS AMAR UNS AOS OUTROS / COMO EU AMEI VOCÊS.\nSE AMOR ENTRE VOCÊS / TODOS RECONHECER VOCÊS MEUS DISCÍPULOS.",
  "Jo 14,1-12": "JESUS: CORAÇÃO NÃO PERTURBAR / CONFIAR DEUS / CONFIAR EM MIM.\nCASA PAI MUITAS MORADAS / EU IR PREPARAR LUGAR / VOLTAR BUSCAR VOCÊS.\nTOMÉ: CAMINHO NÃO SABEMOS.\nJESUS: EU CAMINHO / VERDADE / VIDA; NINGUÉM VAI PAI SENÃO POR MIM.\nFILIPE PEDIR MOSTRAR PAI.\nJESUS: QUEM ME VÊ / VÊ PAI.\nQUEM CRER EM MIM / OBRAS FARÁ.",
  "Jo 14,15-21": "JESUS: SE VOCÊS ME AMAR / GUARDAR MANDAMENTOS.\nEU PEDIR PAI / ELE DAR OUTRO DEFENSOR / ESPÍRITO VERDADE / PERMANECER COM VOCÊS.\nEU NÃO DEIXAR VOCÊS ÓRFÃOS / VOLTAR.\nPORQUE EU VIVO / VOCÊS VIVER.\nQUEM RECEBER E GUARDAR MEUS MANDAMENTOS / ESSE ME AMA / PAI AMAR / EU ME REVELAR.",
  "Jo 14,23-29": "JESUS: QUEM ME AMA / GUARDAR MINHA PALAVRA.\nPAI AMAR / NÓS VIR / MORADA FAZER NELE.\nESPÍRITO SANTO / PAI ENVIAR / ENSINAR TUDO / LEMBRAR MINHAS PALAVRAS.\nPAZ EU DEIXAR / MINHA PAZ DAR / DIFERENTE MUNDO.\nCORAÇÃO NÃO PERTURBAR / MEDO NÃO.\nEU IR E VOLTAR / DIGO ANTES PARA VOCÊS CRER.",
  "Jo 15,1-8": "(CENÁRIO: videira e ramos)\nJESUS: EU VIDEIRA VERDADEIRA / PAI AGRICULTOR.\nRAMO SEM FRUTO / CORTAR; RAMO COM FRUTO / PODAR PARA MAIS FRUTO.\nVOCÊS PERMANECER EM MIM / EU EM VOCÊS.\nRAMO SOZINHO FRUTO NÃO / SEM MIM VOCÊS NADA.\nQUEM PERMANECER / FRUTO MUITO.\nISSO GLORIFICAR PAI: VOCÊS FRUTO DAR / SER MEUS DISCÍPULOS.",
  "Jo 15,9-17": "JESUS: COMO PAI ME AMOU / EU AMEI VOCÊS / PERMANECER MEU AMOR.\nGUARDAR MANDAMENTOS / PERMANECER AMOR.\nMEU MANDAMENTO: AMAR UNS AOS OUTROS COMO EU AMEI.\nAMOR MAIOR: DAR VIDA AMIGOS.\nVOCÊS NÃO SERVOS / AMIGOS.\nNÃO VOCÊS ESCOLHERAM MIM / EU ESCOLHI VOCÊS / IR E DAR FRUTO.",
  "Jo 16,12-15": "JESUS: AINDA MUITO PARA DIZER / VOCÊS AGORA NÃO SUPORTAR.\nESPÍRITO VERDADE VIR / GUIAR TODA VERDADE.\nELE NÃO FALAR POR SI / ANUNCIAR O QUE OUVIR / FUTURO MOSTRAR.\nELE ME GLORIFICAR / RECEBER DO QUE É MEU E ANUNCIAR.\nTUDO DO PAI É MEU.",
  "Jo 18,33-37": "(CENÁRIO: PILATOS interroga JESUS)\nPILATOS: VOCÊ REI DOS JUDEUS?\nJESUS: MEU REINO NÃO É DESTE MUNDO / SE FOSSE, SERVOS LUTAR.\nPILATOS: ENTÃO VOCÊ REI?\nJESUS: PARA ISSO NASCI / PARA ISSO VIM MUNDO / TESTEMUNHAR VERDADE.\nQUEM PERTENCE VERDADE / OUVIR MINHA VOZ.",
  "Jo 2,1-11": "(CENÁRIO: casamento em Caná; Maria, Jesus, discípulos, serventes)\nVINHO ACABAR.\nMARIA DIZER JESUS / DEPOIS SERVOS: FAÇAM O QUE ELE MANDAR.\nJESUS MANDAR ENCHER TALHAS ÁGUA.\nÁGUA TRANSFORMAR VINHO / MELHOR VINHO.\nPRIMEIRO SINAL / JESUS GLÓRIA MANIFESTAR / DISCÍPULOS CRER.",
  "Jo 2,13-25": "(CENÁRIO: templo; vendedores; cambistas)\nJESUS ENTRAR TEMPLO / VER COMÉRCIO.\nELE EXPULSAR VENDEDORES / DERRUBAR MESAS / DIZER: CASA PAI NÃO FAZER MERCADO.\nLÍDERES PEDIR SINAL.\nJESUS: DESTRUIR ESTE TEMPLO / TRÊS DIAS EU LEVANTAR.\nELE FALAR DO CORPO DELE.\nDEPOIS RESSURREIÇÃO / DISCÍPULOS LEMBRAR E CRER.",
  "Jo 20,1-9": "(CENÁRIO: madrugada; sepulcro; Maria Madalena → Pedro e outro discípulo)\nMARIA CHEGAR / PEDRA RETIRADA / CORRER AVISAR.\nPEDRO E OUTRO DISCÍPULO CORRER SEPULCRO.\nLENÇÓIS NO CHÃO / SUDÁRIO SEPARADO.\nOUTRO DISCÍPULO ENTRAR / VER / CRER.\nAINDA NÃO ENTENDER ESCRITURA: JESUS DEVIA RESSUSCITAR.",
  "Jo 20,19-23": "(CENÁRIO: discípulos fechados por medo)\nJESUS APARECER NO MEIO / DIZER: PAZ A VOCÊS.\nMOSTRAR MÃOS E LADO / DISCÍPULOS ALEGRAR.\nJESUS: COMO PAI ME ENVIOU / EU ENVIO VOCÊS.\nSOPRAR SOBRE ELES: RECEBAM ESPÍRITO SANTO.\nPECADOS PERDOAR / RETER / MISSÃO CONFIADA.",
  "Jo 20,19-31": "(CENÁRIO: primeiro encontro sem Tomé → oito dias depois com Tomé)\nJESUS ENTRAR PORTAS FECHADAS / PAZ A VOCÊS / MOSTRAR FERIDAS.\nENVIAR DISCÍPULOS / DAR ESPÍRITO.\nTOMÉ NÃO ESTAVA / DIZER: SE EU NÃO VER, NÃO CRER.\nOITO DIAS DEPOIS JESUS VOLTAR / CONVIDAR TOMÉ TOCAR.\nTOMÉ: MEU SENHOR / MEU DEUS.\nJESUS: FELIZES QUEM NÃO VIU E CREU.\nSINAIS ESCRITOS PARA VOCÊS CRER E TER VIDA.",
  "Jo 21,1-19": "(CENÁRIO: mar; discípulos pescando; JESUS na margem)\nNOITE TODA / NADA PEGAR.\nJESUS MANDAR LANÇAR REDE / PEIXES MUITOS.\nDISCÍPULO RECONHECER: É SENHOR.\nJESUS PREPARAR PÃO E PEIXE / COMER COM ELES.\nDEPOIS JESUS PERGUNTAR PEDRO TRÊS VEZES: VOCÊ ME AMA?\nPEDRO RESPONDER SIM.\nJESUS: CUIDAR MINHAS OVELHAS / SEGUIR-ME.",
  "Jo 3,14-21": "JESUS: COMO SERPENTE DESERTO FOI LEVANTADA / FILHO HOMEM TAMBÉM SER LEVANTADO / QUEM CRER TER VIDA ETERNA.\nDEUS AMAR MUNDO / DAR FILHO ÚNICO / NÃO PARA CONDENAR / MAS SALVAR.\nQUEM CRER / NÃO CONDENADO.\nLUZ VEIO MUNDO / ALGUNS PREFERIR ESCURIDÃO.\nQUEM PRATICAR VERDADE / VIR PARA LUZ.",
  "Jo 3,16-18": "DEUS AMAR MUNDO TANTO / DAR FILHO ÚNICO.\nQUEM CRER NELE / NÃO SE PERDER / TER VIDA ETERNA.\nDEUS NÃO ENVIAR FILHO PARA CONDENAR MUNDO / MAS PARA SALVAR.\nQUEM CRER / NÃO CONDENADO; QUEM NÃO CRER / JÁ ESCOLHER REJEITAR.",
  "Jo 4,5-42": "(CENÁRIO: poço de Jacó; JESUS e mulher samaritana; depois discípulos e cidade)\nJESUS PEDIR ÁGUA / MULHER SURPRESA JUDEU FALAR SAMARITANA.\nJESUS OFERECER ÁGUA VIVA / FONTE VIDA ETERNA.\nELE REVELAR VIDA DELA / ELA RECONHECER PROFETA.\nJESUS ENSINAR ADORAÇÃO EM ESPÍRITO E VERDADE.\nMULHER: MESSIAS VIRÁ. JESUS: SOU EU.\nELA DEIXAR CÂNTARO / IR CIDADE / CHAMAR POVO.\nMUITOS CRER PRIMEIRO PELO TESTEMUNHO DELA / DEPOIS OUVIR JESUS / CONFESSAR SALVADOR MUNDO.",
  "Jo 6,1-15": "(CENÁRIO: grande multidão; monte; cinco pães e dois peixes)\nJESUS VER MULTIDÃO / PERGUNTAR COMO ALIMENTAR.\nMENINO TER CINCO PÃES / DOIS PEIXES.\nJESUS AGRADECER / DISTRIBUIR / TODOS COMER ATÉ SATISFEITOS.\nSOBRAS / DOZE CESTOS.\nPOVO QUERER FAZER JESUS REI / ELE AFASTAR SOZINHO.",
  "Jo 6,24-35": "MULTIDÃO PROCURAR JESUS.\nJESUS: VOCÊS ME BUSCAR PORQUE COMERAM PÃO / NÃO PORQUE ENTENDERAM SINAL.\nTRABALHAR NÃO SÓ PELA COMIDA QUE ACABA / MAS ALIMENTO VIDA ETERNA.\nOBRA DE DEUS: CRER NAQUELE QUE ELE ENVIOU.\nPOVO PEDIR PÃO DO CÉU.\nJESUS: EU PÃO DA VIDA / QUEM VEM A MIM NÃO TER FOME / QUEM CRER NÃO TER SEDE.",
  "Jo 6,41-51": "JUDEUS MURMURAR: COMO ELE DIZ DESCER DO CÉU?\nJESUS: NINGUÉM VEM A MIM SE PAI NÃO ATRAIR / EU RESSUSCITAR ÚLTIMO DIA.\nQUEM ESCUTA PAI / VEM A MIM.\nEU PÃO DA VIDA.\nPAIS COMERAM MANÁ E MORRERAM.\nPÃO QUE DESCE CÉU / QUEM COMER NÃO MORRER.\nPÃO QUE EU DAR / MINHA CARNE / VIDA DO MUNDO.",
  "Jo 6,51-58": "JESUS: EU PÃO VIVO DESCIDO CÉU.\nQUEM COMER DESTE PÃO / VIVER PARA SEMPRE.\nPÃO QUE EU DAR / MINHA CARNE / VIDA MUNDO.\nQUEM COMER MINHA CARNE E BEBER MEU SANGUE / TER VIDA ETERNA / EU RESSUSCITAR.\nQUEM COME E BEBE / PERMANECER EM MIM / EU NELE.\nASSIM COMO EU VIVO PELO PAI / QUEM ME RECEBE VIVER POR MIM.",
  "Jo 6,60-69": "MUITOS DISCÍPULOS: ESSA PALAVRA DIFÍCIL / QUEM ACEITAR?\nJESUS SABER MURMURAÇÃO / DIZER ESPÍRITO DAR VIDA / CARNE SOZINHA NÃO.\nMUITOS ABANDONAR / NÃO CAMINHAR MAIS COM ELE.\nJESUS PERGUNTAR DOZE: VOCÊS TAMBÉM QUEREM IR?\nPEDRO: SENHOR / PARA QUEM IREMOS? TU TENS PALAVRAS VIDA ETERNA.\nNÓS CREMOS / TU SANTO DE DEUS.",
  "Jo 8,1-11": "(CENÁRIO: templo; mulher no centro; acusadores ao redor; JESUS abaixa e escreve)\nLÍDERES TRAZER MULHER ACUSADA ADULTÉRIO / TESTAR JESUS / PEDIR JULGAMENTO.\nJESUS: QUEM SEM PECADO / PRIMEIRO ATIRAR PEDRA.\nUM POR UM SAIR.\nJESUS E MULHER FICAR.\nJESUS: NINGUÉM CONDENOU? EU TAMBÉM NÃO CONDENO.\nVAI / PECAR NÃO MAIS.",
  "Jo 9,1-41": "(CENÁRIO: cego de nascença → cura → interrogatórios → encontro final com JESUS)\nJESUS VER HOMEM CEGO / FAZER LAMA / PASSAR OLHOS / MANDAR LAVAR SILOÉ.\nHOMEM LAVAR / VOLTAR VENDO.\nVIZINHOS E FARISEUS QUESTIONAR / ELE TESTEMUNHAR: ERA CEGO / AGORA VEJO.\nPAIS TER MEDO / NÃO RESPONDER.\nFARISEUS EXPULSAR HOMEM.\nJESUS ENCONTRAR / PERGUNTAR CRÊ FILHO HOMEM?\nHOMEM: SENHOR EU CREIO / ADORAR.\nJESUS: VIM PARA QUEM NÃO VÊ PASSAR VER / E QUEM DIZ VER REVELAR CEGUEIRA.",

  "Lc 1,1-4": "MUITOS JÁ ESCREVERAM SOBRE ACONTECIMENTOS.\nEU INVESTIGAR TUDO DESDE INÍCIO COM CUIDADO.\nAGORA ORGANIZAR RELATO PARA VOCÊ TEÓFILO / PARA CONHECER FIRMEZA DO ENSINAMENTO RECEBIDO.",
  "Lc 1,26-38": "(CENÁRIO: Nazaré; MARIA; anjo GABRIEL)\nANJO SAUDAR MARIA / DEUS COM ELA.\nMARIA PERTURBADA.\nANJO: MEDO NÃO / VOCÊ CONCEBER FILHO / NOME JESUS / REINO SEM FIM.\nMARIA: COMO ACONTECER?\nESPÍRITO SANTO VIR SOBRE VOCÊ / PODER ALTÍSSIMO COBRIR.\nISABEL TAMBÉM CONCEBEU / PARA DEUS NADA IMPOSSÍVEL.\nMARIA: EU SERVA SENHOR / ACONTEÇA CONFORME TUA PALAVRA.",
  "Lc 1,39-45": "(CENÁRIO: MARIA viaja → casa Zacarias; encontra ISABEL)\nMARIA ENTRAR / SAUDAR ISABEL.\nCRIANÇA NO VENTRE ISABEL SALTAR / ISABEL CHEIA ESPÍRITO SANTO.\nISABEL BENDIZER MARIA E FRUTO VENTRE.\nCOMO MÃE DO MEU SENHOR VIR A MIM?\nFELIZ VOCÊ QUE CREU / PALAVRA SENHOR VAI CUMPRIR.",
  "Lc 10,1-12.17-20": "JESUS ESCOLHER SETENTA E DOIS / ENVIAR DOIS A DOIS ADIANTE.\nCOLHEITA GRANDE / TRABALHADORES POUCOS / PEDIR SENHOR COLHEITA.\nIR COMO CORDEIROS ENTRE LOBOS / LEVAR PAZ / CURAR DOENTES / ANUNCIAR REINO DEUS CHEGOU.\nSE NÃO RECEBEREM / SAIR E TESTEMUNHAR.\nDISCÍPULOS VOLTAR ALEGRES / DEMÔNIOS OBEDECER.\nJESUS: NÃO ALEGRAR SÓ PODER / ALEGRAR NOMES ESCRITOS CÉU.",
  "Lc 10,25-37": "(CENÁRIO: doutor da Lei pergunta → parábola estrada Jerusalém-Jericó)\nDOUTOR: O QUE FAZER PARA VIDA ETERNA?\nJESUS: LEI DIZ O QUÊ?\nAMAR DEUS TODO SER / PRÓXIMO COMO SI.\nELE PERGUNTAR: QUEM MEU PRÓXIMO?\nHOMEM ASSALTADO / FERIDO / CAÍDO.\nSACERDOTE PASSAR / LEVITA PASSAR / NÃO AJUDAR.\nSAMARITANO VER / COMPAIXÃO / CUIDAR FERIDAS / LEVAR HOSPEDARIA / PAGAR.\nJESUS: QUAL DELES FOI PRÓXIMO?\nRESPOSTA: QUEM TEVE MISERICÓRDIA.\nJESUS: VAI / FAZ IGUAL.",
  "Lc 10,38-42": "(CENÁRIO: casa; MARTA servindo; MARIA sentada perto JESUS)\nMARTA OCUPADA MUITOS SERVIÇOS / RECLAMAR: MARIA NÃO AJUDAR.\nJESUS: MARTA, MARTA / VOCÊ PREOCUPADA MUITAS COISAS.\nUMA COISA NECESSÁRIA.\nMARIA ESCOLHEU PARTE MELHOR / NÃO SER TIRADA.",
  "Lc 11,1-13": "DISCÍPULO: SENHOR ENSINAR NÓS ORAR.\nJESUS ENSINAR: PAI / NOME SANTO / REINO VENHA / PÃO CADA DIA / PERDOAR / NÃO DEIXAR CAIR TENTAÇÃO.\nPARÁBOLA AMIGO À MEIA-NOITE / INSISTÊNCIA CONSEGUIR PÃO.\nPEDIR / RECEBER; PROCURAR / ENCONTRAR; BATER / PORTA ABRIR.\nPAI TERRESTRE DAR COISA BOA / PAI CÉU DAR ESPÍRITO SANTO QUEM PEDIR.",
  "Lc 12,13-21": "ALGUÉM PEDIR JESUS RESOLVER HERANÇA.\nJESUS ALERTAR: CUIDADO GANÂNCIA / VIDA NÃO DEPENDER BENS.\nPARÁBOLA HOMEM RICO / COLHEITA GRANDE / CONSTRUIR DEPÓSITOS MAIORES / DIZER A SI: MUITOS BENS / DESCANSAR.\nDEUS: HOJE SUA VIDA SERÁ PEDIDA / PARA QUEM FICARÁ TUDO?\nASSIM QUEM ACUMULAR PARA SI / MAS NÃO SER RICO DIANTE DE DEUS.",
  "Lc 12,32-48": "JESUS: PEQUENO REBANHO / MEDO NÃO / PAI QUER DAR REINO.\nVENDER BENS / DAR AOS POBRES / TESOURO CÉU.\nONDE TESOURO / CORAÇÃO.\nFICAR PRONTOS / LÂMPADAS ACESAS / ESPERAR SENHOR VOLTAR.\nFELIZ SERVO ENCONTRADO VIGIANDO E FIEL.\nQUEM RECEBEU MUITO / MUITO SERÁ PEDIDO.",
  "Lc 12,49-53": "JESUS: VIM TRAZER FOGO TERRA / QUERO QUE ACENDA.\nTENHO BATISMO PARA RECEBER / ANGÚSTIA ATÉ CUMPRIR.\nVOCÊS PENSAR VIM TRAZER PAZ SIMPLES?\nMINHA PRESENÇA EXIGIR DECISÃO / ATÉ FAMÍLIAS PODEM DIVIDIR.",
  "Lc 13,1-9": "PESSOAS CONTAR TRAGÉDIAS / JESUS: VÍTIMAS NÃO ERAM MAIS PECADORAS.\nSE VOCÊS NÃO SE CONVERTEREM / TAMBÉM PERECER.\nPARÁBOLA FIGUEIRA SEM FRUTO.\nDONO QUER CORTAR / CUIDADOR PEDIR MAIS UM ANO / CAVAR / ADUBAR.\nSE DER FRUTO, BEM; SENÃO, DEPOIS CORTAR.",
  "Lc 13,22-30": "JESUS CAMINHAR PARA JERUSALÉM / ALGUÉM PERGUNTAR: POUCOS SERÃO SALVOS?\nJESUS: ESFORÇAR ENTRAR PORTA ESTREITA.\nDEPOIS PORTA FECHAR / ALGUNS DIZER CONHECEM SENHOR / ELE DIZER NÃO CONHEÇO CAMINHO DE VOCÊS.\nPOVOS VIR ORIENTE-OESTE-NORTE-SUL / SENTAR REINO DEUS.\nÚLTIMOS SERÃO PRIMEIROS / PRIMEIROS ÚLTIMOS.",
  "Lc 14,1.7-14": "(CENÁRIO: refeição na casa de fariseu)\nJESUS VER CONVIDADOS ESCOLHER PRIMEIROS LUGARES.\nENSINAR: NÃO PROCURAR LUGAR HONRA / ESCOLHER ÚLTIMO / QUEM SE EXALTA SER HUMILHADO / QUEM SE HUMILHA SER EXALTADO.\nAO ANFITRIÃO: QUANDO DER BANQUETE / CONVIDAR POBRES, ALEIJADOS, MANCOS, CEGOS / ELES NÃO PODEM RETRIBUIR / DEUS RETRIBUIR.",
  "Lc 14,25-33": "MULTIDÃO ACOMPANHAR JESUS.\nJESUS: QUEM QUER ME SEGUIR / DEVE COLOCAR-ME ACIMA DE TODOS / CARREGAR CRUZ.\nANTES CONSTRUIR TORRE / CALCULAR CUSTO.\nANTES REI IR GUERRA / AVALIAR FORÇA.\nASSIM QUEM NÃO RENUNCIAR TUDO / NÃO PODE SER MEU DISCÍPULO.",
  "Lc 15,1-3.11-32": "(CENÁRIO: pecadores aproximam; fariseus reclamam → parábola pai e dois filhos)\nFILHO MAIS NOVO PEDIR HERANÇA / IR LONGE / GASTAR TUDO / PASSAR FOME.\nCAIR EM SI / VOLTAR PAI / CONFESSAR PECADO.\nPAI VER DE LONGE / CORRER / ABRAÇAR / FESTA FAZER: FILHO ESTAVA MORTO / VIVEU; PERDIDO / ENCONTRADO.\nFILHO MAIS VELHO FICAR IRRITADO / RECUSAR ENTRAR.\nPAI SAIR / PEDIR.\nPAI: TUDO MEU É SEU / MAS PRECISAVA ALEGRAR / SEU IRMÃO VOLTOU.",
  "Lc 15,1-32": "PECADORES APROXIMAR JESUS / FARISEUS RECLAMAR.\nJESUS CONTAR TRÊS PARÁBOLAS: OVELHA PERDIDA / PASTOR PROCURAR ATÉ ENCONTRAR; MOEDA PERDIDA / MULHER PROCURAR ATÉ ENCONTRAR; FILHO PERDIDO / PAI RECEBER COM FESTA.\nCÉU ALEGRAR QUANDO PECADOR SE CONVERTER.\nFILHO MAIS VELHO PRECISA APRENDER ALEGRAR COM MISERICÓRDIA DO PAI.",
  "Lc 16,1-13": "JESUS CONTAR ADMINISTRADOR ACUSADO DESPERDIÇAR BENS.\nELE PREPARAR FUTURO USANDO RAPIDEZ E ASTÚCIA.\nJESUS: USAR BENS DESTE MUNDO PARA FAZER BEM / SER FIEL NO POUCO.\nQUEM FIEL POUCO / FIEL MUITO.\nNINGUÉM SERVIR DOIS SENHORES.\nNÃO PODE SERVIR DEUS E DINHEIRO.",
  "Lc 16,19-31": "(CENÁRIO: rico à mesa; Lázaro na porta → depois morte e inversão)\nHOMEM RICO VIVER LUXO / LÁZARO POBRE FERIDO DEITADO PORTA / DESEJAR MIGALHAS.\nAMBOS MORRER.\nLÁZARO CONSOLADO JUNTO ABRAÃO / RICO EM TORMENTO.\nRICO PEDIR AJUDA / ABRAÃO: VIDA ANTES VOCÊ RECEBEU BENS / LÁZARO MALES; AGORA SITUAÇÃO INVERTER / GRANDE ABISMO.\nRICO PEDIR AVISAR IRMÃOS.\nABRAÃO: ELES TÊM MOISÉS E PROFETAS / ESCUTAR.\nSE NÃO ESCUTAR PALAVRA / NEM RESSUSCITADO CONVENCER.",
  "Lc 17,11-19": "(CENÁRIO: caminho Jerusalém; dez leprosos de longe)\nDEZ LEPROSOS CLAMAR: JESUS MESTRE / PIEDADE.\nJESUS: VÃO MOSTRAR SACERDOTES.\nNO CAMINHO / TODOS PURIFICADOS.\nUM VOLTAR / LOUVAR DEUS / CAIR PÉS JESUS / AGRADECER / ERA SAMARITANO.\nJESUS: DEZ FORAM CURADOS / OUTROS NOVE ONDE?\nLEVANTA / TUA FÉ TE SALVOU.",
  "Lc 17,5-10": "APÓSTOLOS: SENHOR / AUMENTAR NOSSA FÉ.\nJESUS: FÉ PEQUENA COMO GRÃO MOSTARDA / PODERIA MANDAR ÁRVORE MUDAR.\nSERVO DEPOIS TRABALHAR CAMPO / AINDA SERVIR SENHOR.\nASSIM VOCÊS / DEPOIS FAZER TUDO ORDENADO / DIZER: SOMOS SERVOS / FIZEMOS DEVER.",
  "Lc 18,1-8": "JESUS ENSINAR ORAR SEMPRE / DESANIMAR NÃO.\nPARÁBOLA JUIZ NÃO TEMER DEUS / NÃO RESPEITAR NINGUÉM.\nVIÚVA INSISTIR: FAZ JUSTIÇA PARA MIM.\nJUIZ POR INSISTÊNCIA DELA / ATENDER.\nJESUS: DEUS FARÁ JUSTIÇA AOS ELEITOS QUE CLAMAM DIA-NOITE.\nMAS FILHO HOMEM QUANDO VIER / ENCONTRAR FÉ NA TERRA?",
  "Lc 18,9-14": "(CENÁRIO: templo; fariseu e cobrador separados)\nFARISEU ORAR SOBRE SI / COMPARAR-SE / DIZER JEJUA E DÁ DÍZIMO.\nCOBRADOR LONGE / NÃO LEVANTAR OLHOS / BATER PEITO: DEUS, MISERICÓRDIA DE MIM PECADOR.\nJESUS: ESTE VOLTAR JUSTIFICADO / OUTRO NÃO.\nQUEM SE EXALTAR SER HUMILHADO / QUEM SE HUMILHAR SER EXALTADO.",
  "Lc 19,1-10": "(CENÁRIO: Jericó; multidão; Zaqueu sobe árvore)\nZAQUEU CHEFE COBRADORES / RICO / QUERER VER JESUS.\nBAIXO / MULTIDÃO IMPEDIR / SUBIR ÁRVORE.\nJESUS OLHAR: ZAQUEU DESCE / HOJE FICAR SUA CASA.\nPOVO MURMURAR JESUS HOSPEDAR PECADOR.\nZAQUEU: METADE BENS POBRES / SE ROUBEI / DEVOLVER QUATRO VEZES.\nJESUS: HOJE SALVAÇÃO CHEGOU ESTA CASA / FILHO HOMEM VEIO PROCURAR E SALVAR PERDIDO.",
  "Lc 19,28-40": "(CENÁRIO: JESUS aproxima Jerusalém; jumentinho; discípulos; multidão)\nJESUS ENVIAR DOIS DISCÍPULOS BUSCAR JUMENTINHO.\nELES ENCONTRAR COMO ELE DISSE / TRAZER / COLOCAR MANTOS.\nJESUS MONTAR / POVO ESTENDER MANTOS CAMINHO.\nMULTIDÃO LOUVAR DEUS / REI QUE VEM NOME SENHOR / PAZ CÉU / GLÓRIA.\nFARISEUS PEDIR CALAR DISCÍPULOS.\nJESUS: SE ELES CALAREM / PEDRAS CLAMARÃO.",
  "Lc 2,1-14": "(CENÁRIO: decreto → viagem Nazaré-Belém → manjedoura → campo dos pastores)\nCÉSAR ORDENAR RECENSEAMENTO.\nJOSÉ E MARIA IR BELÉM / MARIA GRÁVIDA.\nELA DAR À LUZ FILHO / ENVOLVER FAIXAS / DEITAR MANJEDOURA / NÃO HAVER LUGAR HOSPEDARIA.\nPASTORES CAMPO / ANJO APARECER / MEDO.\nANJO: NÃO TENHAM MEDO / HOJE NASCEU SALVADOR / CRISTO SENHOR / SINAL: MENINO NA MANJEDOURA.\nMULTIDÃO ANJOS: GLÓRIA DEUS / PAZ TERRA.",
  "Lc 2,15-20": "ANJOS PARTIR / PASTORES DECIDIR IR BELÉM.\nENCONTRAR MARIA / JOSÉ / MENINO MANJEDOURA.\nPASTORES CONTAR MENSAGEM RECEBIDA / TODOS ADMIRAR.\nMARIA GUARDAR ACONTECIMENTOS / MEDITAR CORAÇÃO.\nPASTORES VOLTAR / GLORIFICAR E LOUVAR DEUS.",
  "Lc 2,16-21": "PASTORES IR DEPRESSA / ENCONTRAR MARIA / JOSÉ / MENINO MANJEDOURA.\nCONTAR O QUE ANJO DISSE / TODOS ADMIRAR.\nMARIA GUARDAR TUDO CORAÇÃO / MEDITAR.\nOITO DIAS DEPOIS / MENINO CIRCUNCIDADO / NOME JESUS / NOME DADO PELO ANJO.",
  "Lc 2,22-40": "(CENÁRIO: templo; Maria e José apresentam Jesus; Simeão; Ana)\nPAIS LEVAR JESUS JERUSALÉM / CUMPRIR LEI / OFERECER SACRIFÍCIO.\nSIMEÃO JUSTO / ESPÍRITO CONDUZIR / PEGAR MENINO / LOUVAR: MEUS OLHOS VIRAM SALVAÇÃO / LUZ NAÇÕES / GLÓRIA ISRAEL.\nDIZER A MARIA: ESTE MENINO SER SINAL CONTRADIÇÃO / ESPADA ATRAVESSAR SUA ALMA.\nANA PROFETISA CHEGAR / AGRADECER / FALAR DO MENINO.\nFAMÍLIA VOLTAR NAZARÉ / MENINO CRESCER / SABEDORIA E GRAÇA.",
  "Lc 2,41-52": "(CENÁRIO: peregrinação Jerusalém; JESUS 12 anos; templo)\nFAMÍLIA IR PÁSCOA JERUSALÉM.\nNA VOLTA / JESUS FICAR / PAIS NÃO SABER.\nTRÊS DIAS PROCURAR / ENCONTRAR TEMPLO / ENTRE DOUTORES / OUVIR E PERGUNTAR.\nMARIA: POR QUE FAZER ISSO? NÓS ANGUSTIADOS.\nJESUS: NÃO SABIAM QUE DEVO ESTAR NAS COISAS DO MEU PAI?\nPAIS NÃO COMPREENDER.\nJESUS VOLTAR NAZARÉ / OBEDECER / CRESCER SABEDORIA / ESTATURA / GRAÇA.",
  "Lc 20,27-38": "SADUCEUS QUE NEGAM RESSURREIÇÃO / FAZER CASO MULHER COM SETE MARIDOS.\nPERGUNTAR: NA RESSURREIÇÃO / ESPOSA DE QUEM?\nJESUS: VIDA FUTURA NÃO FUNCIONAR COMO CASAMENTO DESTE MUNDO.\nRESSUSCITADOS NÃO MORRER / SER FILHOS DE DEUS.\nMOISÉS MESMO MOSTRAR: DEUS É DE ABRAÃO / ISAAC / JACÓ.\nDEUS NÃO É DE MORTOS / MAS DE VIVOS.",
  "Lc 21,25-28.34-36": "SINAIS SOL / LUA / ESTRELAS / NAÇÕES ANGUSTIADAS.\nFILHO HOMEM VIR NUVEM COM PODER E GLÓRIA.\nQUANDO ISSO COMEÇAR / LEVANTAR CABEÇA / LIBERTAÇÃO PRÓXIMA.\nCUIDADO CORAÇÃO PESADO POR EXCESSOS E PREOCUPAÇÕES.\nVIGIAR E ORAR SEMPRE / FICAR DE PÉ DIANTE FILHO HOMEM.",
  "Lc 21,5-19": "ALGUNS ADMIRAR TEMPLO.\nJESUS: DIAS VIRÃO / PEDRA SOBRE PEDRA NÃO FICAR.\nPERGUNTAR QUANDO / QUAL SINAL.\nJESUS: NÃO SE ENGANAR / GUERRAS E TUMULTOS NÃO SIGNIFICAR FIM IMEDIATO.\nHAVER PERSEGUIÇÃO / ENTREGAR VOCÊS / ISSO SER OPORTUNIDADE TESTEMUNHO.\nEU DAR SABEDORIA / ADVERSÁRIOS NÃO PODER RESISTIR.\nVOCÊS SER ODIADOS / MAS PERSEVERANDO GANHAR VIDA.",
  "Lc 22,14–23,56": "(CENÁRIO: ceia → Getsêmani → julgamento → caminho → cruz → sepulcro)\nJESUS CEAR COM DISCÍPULOS / PÃO DAR COMO CORPO / CÁLICE COMO NOVA ALIANÇA.\nANUNCIAR TRAIÇÃO / ENSINAR MAIOR SERVIR.\nPEDRO PROMETER FIDELIDADE / JESUS PREDIZER NEGAÇÃO.\nGETSÊMANI / JESUS ORAR: PAI, TUA VONTADE.\nJUDAS CHEGAR / JESUS PRESO.\nPEDRO NEGAR TRÊS VEZES / CHORAR.\nCONSELHO E PILATOS INTERROGAR / POVO PEDIR CRUCIFICAÇÃO.\nJESUS CARREGAR CRUZ / SIMÃO CIRENE AJUDAR.\nNA CRUZ / PERDOAR / PROMETER PARAÍSO AO CRIMINOSO ARREPENDIDO.\nJESUS ENTREGAR ESPÍRITO / MORRER.\nJOSÉ ARIMATEIA COLOCAR CORPO SEPULCRO / MULHERES OBSERVAR.",
  "Lc 23,35-43": "(CENÁRIO: JESUS na cruz; líderes, soldados e dois condenados)\nLÍDERES ZOMBAR: SALVOU OUTROS / SALVE A SI.\nSOLDADOS ZOMBAR / PLACA: REI JUDEUS.\nUM CONDENADO INSULTAR.\nOUTRO REPREENDER: NÓS RECEBEMOS CONSEQUÊNCIA / ELE NADA FEZ.\nELE DIZER: JESUS, LEMBRA DE MIM QUANDO VIER TEU REINO.\nJESUS: HOJE VOCÊ ESTARÁ COMIGO PARAÍSO.",
  "Lc 24,13-35": "(CENÁRIO: dois discípulos caminhando Jerusalém → Emaús; JESUS se aproxima)\nDISCÍPULOS TRISTES / FALAR SOBRE JESUS CRUCIFICADO E TÚMULO VAZIO.\nJESUS NÃO RECONHECIDO / EXPLICAR MOISÉS E PROFETAS / MESSIAS DEVIA SOFRER E ENTRAR GLÓRIA.\nCHEGAR ALDEIA / DISCÍPULOS PEDIR: FICA CONOSCO.\nMESA / JESUS PEGAR PÃO / ABENÇOAR / PARTIR / DAR.\nOLHOS ABRIR / RECONHECER / JESUS DESAPARECER.\nELES: CORAÇÃO ARDIA NO CAMINHO.\nVOLTAR JERUSALÉM / ANUNCIAR.",
  "Lc 24,35-48": "DISCÍPULOS CONTAR O QUE ACONTECEU EM EMAÚS / RECONHECER JESUS AO PARTIR PÃO.\nJESUS APARECER NO MEIO / PAZ A VOCÊS.\nELES MEDO / PENSAR ESPÍRITO.\nJESUS MOSTRAR MÃOS E PÉS / COMER PEIXE DIANTE DELES.\nABRIR MENTE PARA ENTENDER ESCRITURAS.\nMESSIAS SOFRER / RESSUSCITAR TERCEIRO DIA / CONVERSÃO E PERDÃO SER PREGADOS A TODAS NAÇÕES.\nVOCÊS SÃO TESTEMUNHAS.",
  "Lc 24,46-53": "JESUS: ESTÁ ESCRITO / MESSIAS SOFRER E RESSUSCITAR TERCEIRO DIA.\nEM NOME DELE / CONVERSÃO E PERDÃO SER ANUNCIADOS TODAS NAÇÕES / COMEÇAR JERUSALÉM.\nVOCÊS TESTEMUNHAS.\nEU ENVIAREI PROMESSA PAI / FIQUEM ATÉ RECEBER FORÇA DO ALTO.\nJESUS LEVAR DISCÍPULOS BETÂNIA / ABENÇOAR / SER ELEVADO CÉU.\nDISCÍPULOS ADORAR / VOLTAR JERUSALÉM COM ALEGRIA.",
  "Lc 3,1-6": "TEMPO IMPERADORES E GOVERNADORES / PALAVRA DEUS CHEGAR JOÃO NO DESERTO.\nJOÃO PERCORRER REGIÃO JORDÃO / PREGAR BATISMO CONVERSÃO / PERDÃO PECADOS.\nISAÍAS: VOZ NO DESERTO / PREPARAR CAMINHO SENHOR / ENDIREITAR ESTRADAS / VALES LEVANTAR / MONTES ABAIXAR.\nTODOS VER SALVAÇÃO DEUS.",
  "Lc 3,10-18": "MULTIDÕES PERGUNTAR JOÃO: O QUE FAZER?\nQUEM TEM DUAS TÚNICAS / DIVIDIR; QUEM TEM COMIDA / PARTILHAR.\nCOBRADORES: NÃO COBRAR ALÉM.\nSOLDADOS: NÃO EXTORQUIR / CONTENTAR SALÁRIO.\nPOVO PENSAR JOÃO MESSIAS.\nJOÃO: EU BATIZO ÁGUA / VEM MAIS FORTE / ELE BATIZAR ESPÍRITO SANTO E FOGO.\nELE SEPARAR TRIGO E PALHA.\nJOÃO ANUNCIAR BOA NOTÍCIA.",
  "Lc 3,15-16.21-22": "POVO ESPERAR / PENSAR JOÃO TALVEZ MESSIAS.\nJOÃO: EU BATIZO ÁGUA / VEM MAIS FORTE / ELE BATIZAR ESPÍRITO SANTO E FOGO.\nQUANDO TODO POVO BATIZADO / JESUS TAMBÉM BATIZADO / ORANDO.\nCÉU ABRIR / ESPÍRITO SANTO DESCER COMO POMBA.\nVOZ CÉU: TU MEU FILHO AMADO / EM TI ME AGRADO.",
  "Lc 4,1-13": "(CENÁRIO: deserto; JESUS e tentador)\nJESUS CHEIO ESPÍRITO / QUARENTA DIAS DESERTO / JEJUAR.\nDIABO TENTAR: PEDRA VIRAR PÃO.\nJESUS RESPONDER ESCRITURA: HOMEM NÃO VIVE SÓ PÃO.\nTENTAR COM REINOS / PEDIR ADORAÇÃO.\nJESUS: ADORAR SOMENTE DEUS.\nTENTAR TEMPLO / MANDAR JOGAR-SE.\nJESUS: NÃO TENTAR SENHOR DEUS.\nDIABO AFASTAR ATÉ OUTRO MOMENTO.",
  "Lc 4,21-30": "(CENÁRIO: sinagoga Nazaré)\nJESUS: HOJE ESTA ESCRITURA CUMPRIU.\nTODOS ADMIRAR / DEPOIS QUESTIONAR: NÃO É FILHO JOSÉ?\nJESUS: PROFETA NÃO ACEITO NA PRÓPRIA TERRA.\nLEMBRAR ELIAS AJUDAR VIÚVA ESTRANGEIRA / ELISEU CURAR NAAMÃ SÍRIO.\nPOVO FICAR FURIOSO / LEVAR JESUS PARA PRECIPÍCIO.\nJESUS PASSAR PELO MEIO / IR EMBORA.",
  "Lc 5,1-11": "(CENÁRIO: lago; barcos; pescadores; multidão)\nJESUS ENSINAR DO BARCO SIMÃO.\nDEPOIS: IR ÁGUA FUNDA / LANÇAR REDES.\nSIMÃO: TRABALHAMOS NOITE TODA / NADA / MAS POR TUA PALAVRA VOU LANÇAR.\nPEGAR PEIXES TANTOS / REDES QUASE ROMPER / OUTRO BARCO AJUDAR.\nSIMÃO CAIR PÉS JESUS: AFASTA DE MIM / PECADOR.\nJESUS: MEDO NÃO / AGORA VOCÊ PESCAR PESSOAS.\nELES DEIXAR TUDO / SEGUIR.",
  "Lc 6,17.20-26": "JESUS OLHAR DISCÍPULOS.\nFELIZES VOCÊS POBRES / REINO DEUS É DE VOCÊS.\nFELIZES FAMINTOS / SERÃO SACIADOS.\nFELIZES QUEM CHORA / VAI RIR.\nFELIZES QUANDO ODIADOS POR CAUSA FILHO HOMEM / RECOMPENSA CÉU.\nMAS AI DE VOCÊS RICOS / JÁ RECEBERAM CONSOLAÇÃO.\nAI SACIADOS / TERÃO FOME.\nAI QUEM AGORA RI / VAI CHORAR.\nAI QUANDO TODOS FALAM BEM / FALSOS PROFETAS TAMBÉM.",
  "Lc 6,27-38": "JESUS: VOCÊS QUE OUVEM / AMAR INIMIGOS / FAZER BEM QUEM ODEIA / ABENÇOAR QUEM AMALDIÇOA / ORAR QUEM MALTRATA.\nQUEM BATER UMA FACE / OFERECER OUTRA.\nCOMO QUEREM QUE PESSOAS FAÇAM A VOCÊS / FAZER A ELAS.\nAMAR SÓ QUEM AMA VOCÊS / QUE MÉRITO?\nSER MISERICORDIOSOS COMO PAI.\nNÃO JULGAR / NÃO CONDENAR / PERDOAR / DAR.\nMEDIDA QUE VOCÊS USAREM / SERÁ USADA PARA VOCÊS.",
  "Lc 6,39-45": "JESUS PARÁBOLA: CEGO GUIAR CEGO? AMBOS CAIR.\nDISCÍPULO NÃO MAIOR QUE MESTRE / BEM FORMADO SER COMO MESTRE.\nPOR-QUE VER CISCO OLHO IRMÃO / NÃO VER TRAVE SEU OLHO?\nPRIMEIRO TIRAR TRAVE SEU / DEPOIS AJUDAR IRMÃO.\nÁRVORE BOA NÃO DAR FRUTO RUIM / ÁRVORE RUIM NÃO DAR FRUTO BOM.\nBOCA FALAR DO QUE CORAÇÃO ESTÁ CHEIO.",
  "Lc 7,1-10": "(CENÁRIO: Cafarnaum; centurião envia anciãos e amigos a JESUS)\nSERVO CENTURIÃO DOENTE QUASE MORRER.\nCENTURIÃO PEDIR JESUS CURAR.\nJESUS IR.\nCENTURIÃO MANDAR: SENHOR / NÃO SOU DIGNO RECEBER-TE CASA / DIZ UMA PALAVRA / SERVO CURARÁ.\nEU TAMBÉM CONHEÇO AUTORIDADE / DOU ORDENS E OBEDECEM.\nJESUS ADMIRAR FÉ / DIZER NEM EM ISRAEL ENCONTREI ASSIM.\nMENSAGEIROS VOLTAR / SERVO CURADO.",
  "Lc 7,11-17": "(CENÁRIO: cidade Naim; cortejo funeral saindo; JESUS chegando)\nMORRER FILHO ÚNICO DE VIÚVA / MULTIDÃO ACOMPANHAR.\nJESUS VER MÃE / COMPAIXÃO / DIZER NÃO CHORE.\nTOCAR CAIXÃO / CORTEJO PARAR.\nJESUS: JOVEM / EU TE DIGO / LEVANTA.\nMORTO SENTAR / COMEÇAR FALAR / JESUS ENTREGAR À MÃE.\nTODOS MEDO E LOUVOR: GRANDE PROFETA SURGIU / DEUS VISITOU POVO.",
  "Lc 7,36–8,3": "(CENÁRIO: casa fariseu; mulher conhecida como pecadora; JESUS à mesa)\nMULHER ENTRAR / CHORAR AOS PÉS JESUS / MOLHAR COM LÁGRIMAS / ENXUGAR CABELO / BEIJAR / PERFUMAR.\nFARISEU PENSAR: SE PROFETA / SABER QUEM ELA É.\nJESUS CONTAR DOIS DEVEDORES / UM DEVER MUITO / OUTRO POUCO / AMBOS PERDOADOS.\nQUEM AMAR MAIS? QUEM MAIS FOI PERDOADO.\nJESUS MOSTRAR CONTRASTE ENTRE ACOLHIMENTO DELA E FALTA DE ACOLHIMENTO DELE.\nDIZER MULHER: PECADOS PERDOADOS / TUA FÉ TE SALVOU / VAI EM PAZ.\nDEPOIS JESUS CAMINHAR CIDADES / MULHERES TAMBÉM ACOMPANHAR E SERVIR.",
  "Lc 9,18-24": "JESUS ORAR / DISCÍPULOS PERTO.\nPERGUNTAR: POVO DIZ QUE EU SOU QUEM?\nRESPOSTAS: JOÃO / ELIAS / PROFETA.\nJESUS: E VOCÊS?\nPEDRO: CRISTO DE DEUS.\nJESUS ANUNCIAR: FILHO HOMEM SOFRER / SER REJEITADO / MORTO / TERCEIRO DIA RESSUSCITAR.\nA TODOS: QUEM QUER ME SEGUIR / NEGAR A SI / TOMAR CRUZ CADA DIA / SEGUIR.\nQUEM QUER SALVAR VIDA / PERDER; QUEM PERDER POR MIM / SALVAR.",
  "Lc 9,28-36": "(CENÁRIO: monte; JESUS, Pedro, João, Tiago; depois Moisés e Elias)\nJESUS SUBIR MONTE ORAR.\nENQUANTO ORAR / APARÊNCIA ROSTO MUDAR / ROUPA BRILHAR.\nMOISÉS E ELIAS APARECER / FALAR SOBRE PARTIDA DE JESUS EM JERUSALÉM.\nPEDRO QUERER FAZER TRÊS TENDAS.\nNUVEM COBRIR / DISCÍPULOS MEDO.\nVOZ NUVEM: ESTE É MEU FILHO ESCOLHIDO / OUÇAM ELE.\nDEPOIS JESUS FICAR SOZINHO.",
  "Lc 9,51-62": "TEMPO JESUS SER LEVADO CÉU APROXIMAR / ELE DECIDIR IR JERUSALÉM.\nSAMARITANOS NÃO RECEBER / TIAGO E JOÃO QUERER FOGO DESTRUIR / JESUS REPREENDER.\nNO CAMINHO UM DIZER: SEGUIR-TE ONDE FOR.\nJESUS: FILHO HOMEM NÃO TEM ONDE DESCANSAR CABEÇA.\nOUTRO: DEIXA PRIMEIRO ENTERRAR MEU PAI.\nJESUS: VOCÊ VAI ANUNCIAR REINO.\nOUTRO: PRIMEIRO DESPEDIR FAMÍLIA.\nJESUS: QUEM PÕE MÃO ARADO E OLHA PARA TRÁS / NÃO APTO REINO.",

  "Mc 1,1-8": "INÍCIO BOA NOTÍCIA JESUS CRISTO.\nPROFETAS ANUNCIAR MENSAGEIRO PREPARAR CAMINHO.\nJOÃO APARECER DESERTO / BATISMO CONVERSÃO / PERDÃO.\nPOVO IR / CONFESSAR PECADOS / SER BATIZADO.\nJOÃO: DEPOIS DE MIM VEM MAIS FORTE / EU NÃO DIGNO DESATAR SANDÁLIA.\nEU BATIZAR ÁGUA / ELE BATIZAR ESPÍRITO SANTO.",
  "Mc 1,12-15": "ESPÍRITO LEVAR JESUS DESERTO.\nQUARENTA DIAS / SATANÁS TENTAR / ANIMAIS SELVAGENS / ANJOS SERVIR.\nDEPOIS JOÃO PRESO / JESUS IR GALILEIA / ANUNCIAR BOA NOTÍCIA DEUS.\nTEMPO CUMPRIU / REINO DEUS PRÓXIMO / CONVERTER / CRER EVANGELHO.",
  "Mc 1,14-20": "DEPOIS JOÃO PRESO / JESUS GALILEIA / ANUNCIAR: TEMPO CUMPRIU / REINO PRÓXIMO / CONVERTER / CRER.\nCAMINHAR MAR GALILEIA / VER SIMÃO E ANDRÉ PESCANDO.\nJESUS: VENHAM COMIGO / FAREI VOCÊS PESCADORES DE PESSOAS.\nELES DEIXAR REDES / SEGUIR.\nVER TIAGO E JOÃO / CHAMAR / ELES DEIXAR PAI E BARCO / SEGUIR.",
  "Mc 1,21-28": "(CENÁRIO: sinagoga Cafarnaum)\nJESUS ENSINAR / POVO ADMIRAR AUTORIDADE / NÃO COMO ESCRIBAS.\nHOMEM COM ESPÍRITO IMPURO GRITAR / RECONHECER JESUS SANTO DE DEUS.\nJESUS: CALA / SAI DELE.\nESPÍRITO SACUDIR HOMEM / SAIR.\nTODOS ADMIRAR: NOVO ENSINAMENTO COM AUTORIDADE / ATÉ ESPÍRITOS OBEDECEM.\nFAMA JESUS ESPALHAR.",
  "Mc 1,29-39": "(CENÁRIO: sinagoga → casa Simão → porta da cidade → lugar deserto)\nJESUS ENTRAR CASA SIMÃO / SOGRA DEITADA FEBRE.\nELE PEGAR MÃO / LEVANTAR / FEBRE PASSAR / ELA SERVIR.\nÀ TARDE / CIDADE TODA LEVAR DOENTES E ENDEMONINHADOS / JESUS CURAR MUITOS.\nCEDO / JESUS IR LUGAR DESERTO ORAR.\nDISCÍPULOS PROCURAR: TODOS TE BUSCAM.\nJESUS: VAMOS OUTRAS ALDEIAS / PRECISO PREGAR TAMBÉM / PARA ISSO VIM.",
  "Mc 1,40-45": "LEPROSO APROXIMAR / AJOELHAR / DIZER: SE QUERES / PODES ME PURIFICAR.\nJESUS COMPAIXÃO / TOCAR / DIZER: EU QUERO / FICA PURO.\nLEPRA SUMIR.\nJESUS MANDAR NÃO DIVULGAR / MOSTRAR-SE SACERDOTE / OFERECER O QUE MOISÉS MANDOU.\nHOMEM ESPALHAR NOTÍCIA / JESUS NÃO PODER MAIS ENTRAR ABERTAMENTE CIDADES / POVO IR ATÉ ELE.",
  "Mc 1,7-11": "JOÃO ANUNCIAR: DEPOIS DE MIM VEM MAIS FORTE / EU NÃO DIGNO DESATAR SANDÁLIA.\nEU BATIZAR ÁGUA / ELE BATIZAR ESPÍRITO SANTO.\nJESUS VIR NAZARÉ / JOÃO BATIZAR JORDÃO.\nSAIR ÁGUA / CÉUS ABRIR / ESPÍRITO DESCER COMO POMBA.\nVOZ CÉU: TU MEU FILHO AMADO / EM TI ME AGRADO.",
  "Mc 10,17-30": "HOMEM CORRER / AJOELHAR JESUS: BOM MESTRE / O QUE FAZER PARA VIDA ETERNA?\nJESUS LEMBRAR MANDAMENTOS.\nHOMEM: CUMPRO DESDE JOVEM.\nJESUS OLHAR COM AMOR: UMA COISA FALTA / VENDE O QUE TEM / DÁ POBRES / VEM SEGUIR-ME.\nHOMEM IR TRISTE / MUITOS BENS.\nJESUS: DIFÍCIL RICO ENTRAR REINO / MAS PARA DEUS TUDO POSSÍVEL.\nPEDRO: NÓS DEIXAMOS TUDO.\nJESUS: QUEM DEIXAR POR MIM E EVANGELHO / RECEBER MUITO MAIS COM PERSEGUIÇÕES / E VIDA ETERNA.",
  "Mc 10,2-16": "FARISEUS TESTAR JESUS SOBRE DIVÓRCIO.\nJESUS PERGUNTAR O QUE MOISÉS MANDOU / EXPLICAR PERMISSÃO POR DUREZA CORAÇÃO.\nDESDE CRIAÇÃO / DEUS FEZ HOMEM E MULHER / DOIS SE TORNAR UMA CARNE / O QUE DEUS UNIU / HUMANO NÃO SEPARAR.\nDEPOIS CRIANÇAS LEVADAS A JESUS / DISCÍPULOS IMPEDIR.\nJESUS FICAR INDIGNADO: DEIXEM CRIANÇAS VIR / REINO PERTENCE A QUEM RECEBER COMO CRIANÇA.\nABRAÇAR E ABENÇOAR.",
  "Mc 10,35-45": "TIAGO E JOÃO PEDIR LUGARES HONRA AO LADO JESUS.\nJESUS: VOCÊS NÃO SABEM O QUE PEDEM / PODEM BEBER MEU CÁLICE?\nOUTROS FICAR IRRITADOS.\nJESUS CHAMAR TODOS: GOVERNANTES DOMINAM POVOS / ENTRE VOCÊS NÃO ASSIM.\nQUEM QUER SER GRANDE / SER SERVO.\nQUEM QUER PRIMEIRO / SER ESCRAVO DE TODOS.\nFILHO HOMEM NÃO VEIO SER SERVIDO / MAS SERVIR / DAR VIDA EM RESGATE POR MUITOS.",
  "Mc 10,46-52": "(CENÁRIO: saída Jericó; Bartimeu à beira caminho)\nBARTIMEU CEGO MENDIGO OUVIR JESUS PASSAR / GRITAR: JESUS FILHO DAVI / PIEDADE.\nMUITOS MANDAR CALAR / ELE GRITAR MAIS.\nJESUS PARAR / CHAMAR.\nELE JOGAR MANTO / LEVANTAR / IR JESUS.\nJESUS: O QUE VOCÊ QUER?\nBARTIMEU: QUE EU VEJA.\nJESUS: VAI / TUA FÉ TE SALVOU.\nELE ENXERGAR / SEGUIR JESUS CAMINHO.",
  "Mc 11,1-10 ou Jo 12,12-16": "OPÇÃO MARCOS — JESUS ENVIAR DISCÍPULOS BUSCAR JUMENTINHO / ENTRAR JERUSALÉM / POVO ESTENDER MANTOS E RAMOS / ACLAMAR: HOSANA / BENDITO QUEM VEM NOME SENHOR.\nOPÇÃO JOÃO — MULTIDÃO PEGAR RAMOS / SAIR AO ENCONTRO JESUS / ACLAMAR REI ISRAEL / JESUS MONTAR JUMENTINHO / DISCÍPULOS ENTENDER DEPOIS GLORIFICAÇÃO.",
  "Mc 12,28-34": "ESCRIBA PERGUNTAR JESUS: QUAL PRIMEIRO MANDAMENTO?\nJESUS: OUVIR ISRAEL / SENHOR NOSSO DEUS É ÚNICO / AMAR DEUS TODO CORAÇÃO / ALMA / MENTE / FORÇA.\nSEGUNDO: AMAR PRÓXIMO COMO A SI.\nNENHUM MAIOR QUE ESTES.\nESCRIBA CONCORDAR / AMOR VALE MAIS QUE SACRIFÍCIOS.\nJESUS: VOCÊ NÃO ESTÁ LONGE REINO DEUS.",
  "Mc 12,38-44": "JESUS ALERTAR SOBRE ESCRIBAS QUE BUSCAM HONRA / ROUBAM VIÚVAS / FAZEM ORAÇÕES LONGAS PARA APARECER.\nDEPOIS SENTAR PERTO COFRE TEMPLO / VER PESSOAS OFERTAR.\nRICOS DAR MUITO.\nVIÚVA POBRE DAR DUAS MOEDINHAS.\nJESUS: ELA DEU MAIS QUE TODOS / ELES DERAM SOBRA / ELA NA POBREZA DEU TUDO QUE TINHA PARA VIVER.",
  "Mc 13,24-32": "DEPOIS TRIBULAÇÃO / SOL ESCURECER / LUA NÃO BRILHAR / ESTRELAS CAIR.\nENTÃO VER FILHO HOMEM VIR NUVENS COM PODER E GLÓRIA.\nELE ENVIAR ANJOS / REUNIR ELEITOS.\nFIGUEIRA: QUANDO RAMOS FICAM TENROS / SABER VERÃO PRÓXIMO.\nASSIM QUANDO VER SINAIS / SABER ELE PRÓXIMO.\nCÉU E TERRA PASSAR / MINHAS PALAVRAS NÃO.\nDIA E HORA / NINGUÉM SABE / SOMENTE PAI.",
  "Mc 13,33-37": "JESUS: CUIDADO / VIGIAR / VOCÊS NÃO SABEM QUANDO HORA.\nIGUAL HOMEM VIAJAR / DEIXAR CASA SERVOS / CADA UM TAREFA / PORTEIRO VIGIAR.\nVOCÊS NÃO SABEM QUANDO DONO VOLTAR / TARDE / MEIA-NOITE / MADRUGADA / MANHÃ.\nNÃO DEIXAR ELE ENCONTRAR VOCÊS DORMINDO.\nO QUE DIGO A VOCÊS / DIGO A TODOS: VIGIAR.",
  "Mc 14,1–15,47": "(CENÁRIO: conspiração → unção → ceia → Getsêmani → prisão → julgamento → cruz → sepulcro)\nLÍDERES PLANEJAR PRENDER JESUS / JUDAS COMBINAR ENTREGA.\nMULHER DERRAMAR PERFUME SOBRE JESUS / ELE INTERPRETAR COMO PREPARAÇÃO SEPULTAMENTO.\nCEIA / JESUS DAR PÃO COMO CORPO / CÁLICE COMO SANGUE ALIANÇA.\nGETSÊMANI / JESUS ANGUSTIADO / ORAR AO PAI / DISCÍPULOS DORMIR.\nJUDAS CHEGAR / JESUS PRESO.\nCONSELHO INTERROGAR / PEDRO NEGAR TRÊS VEZES.\nPILATOS ENTREGAR PARA CRUCIFICAÇÃO / SOLDADOS ZOMBAR / COROA ESPINHOS.\nJESUS CRUCIFICADO / MORRER / CORTINA TEMPLO RASGAR.\nCENTURIÃO: VERDADEIRAMENTE ESTE HOMEM FILHO DE DEUS.\nJOSÉ ARIMATEIA PEDIR CORPO / COLOCAR SEPULCRO / MULHERES OBSERVAR.",
  "Mc 16,15-20": "JESUS DIZER DISCÍPULOS: IR MUNDO TODO / ANUNCIAR EVANGELHO TODA CRIAÇÃO.\nQUEM CRER E FOR BATIZADO / SALVAR.\nSINAIS ACOMPANHAR QUEM CRER.\nSENHOR JESUS DEPOIS FALAR / SER ELEVADO CÉU / SENTAR DIREITA DEUS.\nDISCÍPULOS SAIR PREGAR EM TODO LUGAR / SENHOR AGIR COM ELES / CONFIRMAR PALAVRA.",
  "Mc 2,1-12": "(CENÁRIO: casa lotada; paralítico descido pelo teto)\nQUATRO HOMENS TRAZER PARALÍTICO / NÃO CONSEGUIR ENTRAR / ABRIR TETO / DESCER MACA.\nJESUS VER FÉ / DIZER: FILHO / PECADOS PERDOADOS.\nESCRIBAS PENSAR BLASFÊMIA / SÓ DEUS PERDOA.\nJESUS SABER PENSAMENTO / PERGUNTAR O QUE MAIS FÁCIL DIZER.\nPARA MOSTRAR FILHO HOMEM TEM AUTORIDADE PERDOAR / MANDAR PARALÍTICO: LEVANTA / PEGA MACA / VAI CASA.\nELE LEVANTAR / TODOS GLORIFICAR DEUS.",
  "Mc 2,18-22": "PESSOAS PERGUNTAR JESUS: DISCÍPULOS JOÃO E FARISEUS JEJUAM / SEUS NÃO.\nJESUS: CONVIDADOS CASAMENTO PODEM JEJUAR ENQUANTO NOIVO ESTÁ COM ELES?\nDIAS VIRÃO NOIVO SER TIRADO / ENTÃO JEJUAR.\nREMENDO NOVO EM ROUPA VELHA / RASGAR MAIS.\nVINHO NOVO EM ODRES VELHOS / ROMPER.\nVINHO NOVO / ODRES NOVOS.",
  "Mc 2,23–3,6": "SÁBADO / DISCÍPULOS COLHER ESPIGAS.\nFARISEUS ACUSAR.\nJESUS LEMBRAR DAVI COMER PÃES CONSAGRADOS POR NECESSIDADE.\nSÁBADO FOI FEITO PARA HUMANO / HUMANO NÃO PARA SÁBADO / FILHO HOMEM SENHOR SÁBADO.\nOUTRO SÁBADO SINAGOGA / HOMEM MÃO SECA.\nJESUS PERGUNTAR: SÁBADO FAZER BEM OU MAL / SALVAR OU MATAR?\nELES CALAR.\nJESUS CURAR MÃO / FARISEUS PLANEJAR MATAR JESUS.",
  "Mc 3,20-35": "JESUS CASA / MULTIDÃO / NEM PODER COMER.\nFAMÍLIA OUVIR / IR BUSCAR / DIZER ELE FORA DE SI.\nESCRIBAS DIZER: ELE EXPULSA DEMÔNIOS POR CHEFE DEMÔNIOS.\nJESUS: REINO DIVIDIDO CONTRA SI NÃO PERMANECE / SATANÁS NÃO EXPULSA SATANÁS.\nPECADOS PODEM SER PERDOADOS / MAS REJEITAR OBRA ESPÍRITO SANTO É GRAVE.\nMÃE E IRMÃOS CHEGAR / CHAMAR.\nJESUS OLHAR QUEM AO REDOR: QUEM FAZ VONTADE DEUS / ESSE MEU IRMÃO / IRMÃ / MÃE.",
  "Mc 4,26-34": "JESUS: REINO DEUS COMO HOMEM ESPALHAR SEMENTE / DORMIR E ACORDAR / SEMENTE BROTAR SEM ELE SABER COMO.\nTERRA PRODUZ POR SI / QUANDO FRUTO MADURO / COLHEITA.\nREINO TAMBÉM COMO GRÃO MOSTARDA / MENOR SEMENTE / DEPOIS CRESCER GRANDE / AVES ABRIGAR.\nJESUS ENSINAR POR PARÁBOLAS CONFORME PODIAM ENTENDER.",
  "Mc 4,35-41": "(CENÁRIO: barco à noite; tempestade; JESUS dormindo)\nJESUS: VAMOS OUTRA MARGEM.\nTEMPESTADE FORTE / ONDAS ENTRAR BARCO.\nJESUS DORMIR.\nDISCÍPULOS ACORDAR: MESTRE / NÃO TE IMPORTA QUE MORRAMOS?\nJESUS LEVANTAR / REPREENDER VENTO / MAR: CALA / FICA QUIETO.\nVENTO PARAR / CALMAR.\nJESUS: POR QUE MEDO? AINDA NÃO TÊM FÉ?\nDISCÍPULOS TEMER: QUEM É ESTE / VENTO E MAR OBEDECEM?",
  "Mc 5,21-43": "(CENÁRIO: multidão; Jairo → caminho → mulher doente → casa Jairo)\nJAIRO AJOELHAR / FILHA MORRENDO / PEDIR JESUS IR.\nNO CAMINHO MULHER DOZE ANOS HEMORRAGIA / TOCAR ROUPA JESUS / SER CURADA.\nJESUS PERGUNTAR QUEM TOCOU / MULHER TREMER / CONTAR VERDADE.\nJESUS: FILHA / TUA FÉ TE SALVOU / VAI EM PAZ.\nCHEGAR NOTÍCIA: FILHA JAIRO MORREU.\nJESUS: MEDO NÃO / APENAS CRER.\nCASA / PEGAR MÃO MENINA / MANDAR LEVANTAR.\nELA LEVANTAR / TODOS ESPANTADOS.",
  "Mc 6,1-6": "JESUS VOLTAR TERRA NATAL / ENSINAR SINAGOGA.\nPESSOAS ADMIRAR / DEPOIS DESPREZAR: NÃO É CARPINTEIRO / FILHO MARIA / CONHECEM FAMÍLIA.\nJESUS: PROFETA SÓ SEM HONRA NA PRÓPRIA TERRA / PARENTES / CASA.\nALI POUCOS MILAGRES POR FALTA FÉ.\nJESUS ADMIRAR INCREDULIDADE / IR ENSINAR ALDEIAS.",
  "Mc 6,30-34": "APÓSTOLOS VOLTAR JESUS / CONTAR TUDO FIZERAM E ENSINARAM.\nJESUS: VENHAM LUGAR DESERTO / DESCANSAR UM POUCO.\nMUITA GENTE IR E VIR / NEM TEMPO COMER.\nELES IR BARCO LUGAR DESERTO.\nPOVO PERCEBER / CORRER A PÉ / CHEGAR ANTES.\nJESUS VER MULTIDÃO / COMPAIXÃO / ERAM COMO OVELHAS SEM PASTOR.\nCOMEÇAR ENSINAR MUITAS COISAS.",
  "Mc 6,7-13": "JESUS CHAMAR DOZE / ENVIAR DOIS A DOIS / DAR AUTORIDADE ESPÍRITOS IMPUROS.\nMANDAR LEVAR QUASE NADA CAMINHO / CONFIAR HOSPITALIDADE.\nONDE RECEBEREM / FICAR.\nONDE NÃO RECEBEREM / SAIR / SACUDIR PÓ.\nELES SAIR / PREGAR CONVERSÃO / EXPULSAR DEMÔNIOS / UNGIR DOENTES / CURAR.",
  "Mc 7,1-8.14-15.21-23": "FARISEUS E ESCRIBAS CRITICAR DISCÍPULOS COMER SEM RITO LAVAGEM.\nJESUS CITAR PROFETA: POVO HONRA LÁBIOS / CORAÇÃO LONGE.\nVOCÊS ABANDONAR MANDAMENTO DEUS / SEGURAR TRADIÇÃO HUMANA.\nCHAMAR MULTIDÃO: O QUE ENTRA DE FORA NÃO TORNA PESSOA IMPURA / O QUE SAI DO CORAÇÃO SIM.\nDO CORAÇÃO SAEM MAUS PENSAMENTOS E AÇÕES / ISSO CONTAMINA.",
  "Mc 7,31-37": "(CENÁRIO: região Decápole; homem surdo com dificuldade fala)\nPESSOAS TRAZER HOMEM / PEDIR JESUS IMPOR MÃO.\nJESUS LEVAR À PARTE / TOCAR OUVIDOS / TOCAR LÍNGUA / OLHAR CÉU / SUSPIR.\nDIZER: ABRE-TE.\nOUVIDOS ABRIR / LÍNGUA SOLTAR / FALAR CLARO.\nJESUS PEDIR NÃO CONTAR / MAS QUANTO MAIS PEDIR SILÊNCIO / MAIS DIVULGAR.\nPOVO: ELE FAZ TUDO BEM / SURDOS OUVIR / MUDOS FALAR.",
  "Mc 8,27-35": "JESUS PERGUNTAR DISCÍPULOS: POVO DIZ QUE EU SOU QUEM?\nRESPOSTAS VARIADAS.\nJESUS: E VOCÊS?\nPEDRO: TU ÉS CRISTO.\nJESUS ANUNCIAR FILHO HOMEM SOFRER / REJEITADO / MORTO / RESSUSCITAR.\nPEDRO REPREENDER JESUS.\nJESUS REPREENDER PEDRO: VOCÊ PENSA COMO HUMANOS / NÃO COMO DEUS.\nCHAMAR MULTIDÃO: QUEM QUER SEGUIR / NEGAR A SI / TOMAR CRUZ / SEGUIR.\nQUEM PERDER VIDA POR MIM E EVANGELHO / SALVAR.",
  "Mc 9,2-10": "(CENÁRIO: monte alto; JESUS, Pedro, Tiago, João; Moisés e Elias)\nJESUS TRANSFIGURAR / ROUPA BRANCA BRILHANTE.\nMOISÉS E ELIAS APARECER / FALAR COM ELE.\nPEDRO: FAZER TRÊS TENDAS / NÃO SABER O QUE DIZER / MEDO.\nNUVEM COBRIR / VOZ: ESTE MEU FILHO AMADO / OUÇAM ELE.\nDE REPENTE / SÓ JESUS.\nDESCENDO MONTE / JESUS MANDAR NÃO CONTAR ATÉ FILHO HOMEM RESSUSCITAR.\nDISCÍPULOS PERGUNTAR ENTRE SI O QUE SIGNIFICA RESSUSCITAR.",
  "Mc 9,30-37": "JESUS CAMINHAR GALILEIA / ENSINAR DISCÍPULOS EM PARTICULAR.\nFILHO HOMEM SER ENTREGUE / MORTO / DEPOIS TRÊS DIAS RESSUSCITAR.\nDISCÍPULOS NÃO ENTENDER / MEDO PERGUNTAR.\nEM CASA JESUS: SOBRE O QUE DISCUTIAM CAMINHO?\nELES CALAR / DISCUTIAM QUEM MAIOR.\nJESUS SENTAR / CHAMAR DOZE: QUEM QUER PRIMEIRO / SER ÚLTIMO E SERVO DE TODOS.\nPEGAR CRIANÇA / COLOCAR NO MEIO / ABRAÇAR.\nQUEM RECEBER UMA CRIANÇA EM MEU NOME / RECEBER MIM / E QUEM ME ENVIOU.",
  "Mc 9,38-43.45.47-48": "JOÃO: VIMOS ALGUÉM EXPULSAR DEMÔNIOS EM TEU NOME / NÃO SEGUE CONOSCO / TENTAMOS IMPEDIR.\nJESUS: NÃO IMPEDIR / QUEM FAZ MILAGRE MEU NOME NÃO LOGO FALAR MAL / QUEM NÃO CONTRA NÓS / A FAVOR.\nQUEM DER COPO ÁGUA POR VOCÊS SEREM DE CRISTO / NÃO PERDER RECOMPENSA.\nQUEM FIZER PEQUENO TROPEÇAR / GRAVE.\nSE MÃO / PÉ / OLHO LEVAR PECADO / CORTAR A CAUSA / MELHOR ENTRAR VIDA MUTILADO QUE PERDER-SE.",

  "Mt 1,1-25": "GENEALOGIA MOSTRAR JESUS FILHO DAVI / FILHO ABRAÃO / HISTÓRIA PROMESSA ATÉ CRISTO.\nMARIA GRÁVIDA PELO ESPÍRITO SANTO.\nJOSÉ JUSTO / PENSAR AFASTAR EM SEGREDO.\nANJO SONHO: MEDO NÃO RECEBER MARIA / CRIANÇA VEM ESPÍRITO / NOME JESUS / ELE SALVAR POVO PECADOS.\nISSO CUMPRIR PROFECIA EMANUEL / DEUS CONOSCO.\nJOSÉ OBEDECER / RECEBER MARIA / DAR NOME JESUS.",
  "Mt 1,18-24": "(CENÁRIO: JOSÉ descobre gravidez de MARIA → sonho)\nMARIA PROMETIDA JOSÉ / ANTES VIVEREM JUNTOS / GRÁVIDA ESPÍRITO SANTO.\nJOSÉ JUSTO / NÃO QUERER EXPOR / DECIDIR DEIXAR EM SEGREDO.\nANJO APARECER SONHO: JOSÉ FILHO DAVI / MEDO NÃO RECEBER MARIA / CRIANÇA VEM ESPÍRITO SANTO.\nELA DAR À LUZ FILHO / NOME JESUS / ELE SALVAR POVO PECADOS.\nCUMPRIR PROFECIA: EMANUEL / DEUS CONOSCO.\nJOSÉ ACORDAR / FAZER COMO ANJO MANDOU.",
  "Mt 10,26-33": "JESUS: NÃO TER MEDO DE PESSOAS.\nO QUE ESTÁ ESCONDIDO / SERÁ REVELADO.\nO QUE DIGO NO ESCURO / ANUNCIAR À LUZ.\nNÃO TEMER QUEM MATA CORPO / TEMER PERDER VIDA DIANTE DE DEUS.\nATÉ PASSARINHOS DEUS CUIDA / CABELOS DE VOCÊS CONTADOS.\nVOCÊS VALEM MAIS.\nQUEM ME RECONHECER DIANTE PESSOAS / EU RECONHECER DIANTE PAI.",
  "Mt 10,37-42": "JESUS: QUEM AMA PAI OU MÃE MAIS QUE MIM / NÃO É DIGNO DE MIM.\nQUEM NÃO TOMA CRUZ E ME SEGUE / NÃO É DIGNO.\nQUEM ENCONTRAR VIDA PARA SI / PERDER; QUEM PERDER POR MIM / ENCONTRAR.\nQUEM RECEBE VOCÊS / RECEBE MIM / E QUEM ME ENVIOU.\nQUEM ACOLHER PROFETA / JUSTO / DISCÍPULO PEQUENO / RECEBER RECOMPENSA.",
  "Mt 11,2-11": "(CENÁRIO: JOÃO preso envia discípulos a JESUS)\nJOÃO PERGUNTAR: TU ÉS AQUELE QUE DEVE VIR / OU ESPERAR OUTRO?\nJESUS: VOLTEM E CONTEM O QUE OUVEM E VEEM / CEGOS VEEM / MANCOS ANDAM / LEPROSOS PURIFICADOS / SURDOS OUVEM / MORTOS RESSUSCITAM / POBRES RECEBEM BOA NOTÍCIA.\nDEPOIS JESUS FALAR MULTIDÃO SOBRE JOÃO: NÃO CANIÇO FRÁGIL / NÃO HOMEM LUXO / PROFETA E MAIS QUE PROFETA / MENSAGEIRO PREPARAR CAMINHO.\nENTRE NASCIDOS MULHER / NINGUÉM MAIOR QUE JOÃO.",
  "Mt 11,25-30": "JESUS LOUVAR PAI: ESCONDESTE DOS SÁBIOS ORGULHOSOS / REVELASTE AOS PEQUENOS.\nTUDO PAI ENTREGOU AO FILHO / NINGUÉM CONHECE PAI SENÃO FILHO E QUEM FILHO REVELAR.\nJESUS: VENHAM A MIM TODOS CANSADOS E SOBRECARREGADOS / EU DAREI DESCANSO.\nTOMEM MEU JUGO / APRENDAM DE MIM / MANSO E HUMILDE CORAÇÃO.\nMEU JUGO SUAVE / FARDO LEVE.",
  "Mt 13,1-23": "(CENÁRIO: JESUS no barco; multidão margem → parábola do semeador)\nSEMEADOR SAIR SEMEAR.\nSEMENTES: CAMINHO / AVES COMER; PEDRA / BROTAR E SECAR; ESPINHOS / SUFOCAR; TERRA BOA / FRUTO MUITO.\nJESUS EXPLICAR: SEMENTE = PALAVRA REINO.\nCAMINHO / NÃO ENTENDER / MAL TIRAR.\nPEDRA / RECEBER ALEGRIA / SEM RAIZ / DESISTIR NA DIFICULDADE.\nESPINHOS / PREOCUPAÇÃO E RIQUEZA SUFOCAR.\nTERRA BOA / OUVIR / ENTENDER / DAR FRUTO.",
  "Mt 13,24-43": "JESUS CONTAR: HOMEM SEMEAR BOA SEMENTE / INIMIGO À NOITE SEMEAR JOIO.\nSERVOS QUERER ARRANCAR / DONO: NÃO / PODEM ARRANCAR TRIGO JUNTO / DEIXAR CRESCER ATÉ COLHEITA.\nOUTRAS PARÁBOLAS: GRÃO MOSTARDA PEQUENO → GRANDE; FERMENTO MISTURADO → MASSA TODA.\nDEPOIS EXPLICAR JOIO: SEMEADOR FILHO HOMEM / CAMPO MUNDO / BOA SEMENTE FILHOS REINO / JOIO FILHOS MAL / COLHEITA FIM.\nNO FIM / MAL SEPARADO / JUSTOS BRILHAR REINO PAI.",
  "Mt 13,44-52": "REINO CÉUS COMO TESOURO ESCONDIDO / HOMEM ENCONTRAR / ALEGRIA / VENDER TUDO / COMPRAR CAMPO.\nCOMO COMERCIANTE PROCURAR PÉROLAS / ENCONTRAR UMA GRANDE VALOR / VENDER TUDO / COMPRAR.\nCOMO REDE LANÇADA MAR / PEGAR TODO TIPO PEIXE / DEPOIS SEPARAR BONS E RUINS.\nJESUS PERGUNTAR DISCÍPULOS ENTENDERAM? SIM.\nESCRIBA DISCÍPULO REINO / TIRAR TESOURO COISAS NOVAS E ANTIGAS.",
  "Mt 14,13-21": "(CENÁRIO: lugar deserto; multidão; cinco pães e dois peixes)\nJESUS VER MULTIDÃO / COMPAIXÃO / CURAR DOENTES.\nDISCÍPULOS: MANDA POVO EMBORA COMPRAR COMIDA.\nJESUS: NÃO PRECISAM IR / VOCÊS DÊEM COMER.\nELES: SÓ CINCO PÃES / DOIS PEIXES.\nJESUS MANDAR POVO SENTAR / PEGAR PÃES E PEIXES / OLHAR CÉU / ABENÇOAR / PARTIR / DISCÍPULOS DISTRIBUIR.\nTODOS COMER / SATISFEITOS / SOBRAR DOZE CESTOS.",
  "Mt 14,22-33": "(CENÁRIO: discípulos barco; JESUS monte orando; noite; mar agitado)\nJESUS MANDAR DISCÍPULOS IR OUTRA MARGEM / ELE DISPENSAR MULTIDÃO / SUBIR MONTE ORAR.\nBARCO LONGE / VENTO CONTRÁRIO.\nMADRUGADA JESUS CAMINHAR SOBRE ÁGUA.\nDISCÍPULOS MEDO / PENSAR FANTASMA.\nJESUS: CORAGEM / SOU EU / NÃO TENHAM MEDO.\nPEDRO PEDIR IR ATÉ ELE / CAMINHAR / VER VENTO / TER MEDO / AFUNDAR / CLAMAR.\nJESUS SEGURAR: HOMEM POUCA FÉ / POR QUE DUVIDOU?\nENTRAR BARCO / VENTO PARAR / DISCÍPULOS ADORAR: TU ÉS FILHO DE DEUS.",
  "Mt 15,21-28": "(CENÁRIO: região Tiro e Sidônia; mulher cananeia segue JESUS e discípulos)\nMULHER GRITAR: SENHOR FILHO DAVI / MINHA FILHA TORMENTADA.\nJESUS PRIMEIRO NÃO RESPONDER.\nDISCÍPULOS PEDIR MANDAR ELA EMBORA.\nJESUS FALAR MISSÃO A ISRAEL.\nMULHER AJOELHAR: SENHOR AJUDA.\nJESUS USAR IMAGEM PÃO DOS FILHOS E CACHORRINHOS.\nELA RESPONDER: ATÉ CACHORRINHOS COMEM MIGALHAS QUE CAEM MESA.\nJESUS: MULHER / GRANDE TUA FÉ / ACONTEÇA COMO QUER.\nFILHA CURADA.",
  "Mt 16,13-20": "JESUS PERGUNTAR DISCÍPULOS: POVO DIZ FILHO HOMEM É QUEM?\nRESPOSTAS: JOÃO / ELIAS / JEREMIAS / PROFETA.\nJESUS: E VOCÊS?\nPEDRO: TU ÉS CRISTO / FILHO DEUS VIVO.\nJESUS: FELIZ VOCÊ SIMÃO / ISSO NÃO VEIO CARNE-SANGUE / PAI REVELOU.\nVOCÊ PEDRO / SOBRE ESTA PEDRA EDIFICAR MINHA IGREJA / PORTAS MORTE NÃO VENCER.\nDAR CHAVES REINO / LIGAR E DESLIGAR.",
  "Mt 16,21-27": "JESUS COMEÇAR MOSTRAR DISCÍPULOS: PRECISA IR JERUSALÉM / SOFRER / SER MORTO / TERCEIRO DIA RESSUSCITAR.\nPEDRO PUXAR À PARTE / REPREENDER.\nJESUS: VAI PARA TRÁS DE MIM / VOCÊ PENSA HUMANO / NÃO DEUS.\nA TODOS: QUEM QUER ME SEGUIR / NEGAR A SI / TOMAR CRUZ / SEGUIR.\nQUEM QUER SALVAR VIDA / PERDER; QUEM PERDER POR MIM / ENCONTRAR.\nQUE ADIANTA GANHAR MUNDO / PERDER VIDA?\nFILHO HOMEM VIRÁ GLÓRIA / DAR A CADA UM CONFORME OBRAS.",
  "Mt 17,1-9": "(CENÁRIO: monte alto; JESUS, Pedro, Tiago, João; Moisés e Elias)\nJESUS TRANSFIGURAR / ROSTO BRILHAR SOL / ROUPAS BRANCAS.\nMOISÉS E ELIAS APARECER / CONVERSAR.\nPEDRO QUERER FAZER TRÊS TENDAS.\nNUVEM LUMINOSA COBRIR / VOZ: ESTE MEU FILHO AMADO / NELE ME AGRADO / OUÇAM ELE.\nDISCÍPULOS CAIR COM MEDO.\nJESUS TOCAR: LEVANTEM / NÃO TENHAM MEDO.\nDESCENDO MONTE / MANDAR NÃO CONTAR ATÉ FILHO HOMEM RESSUSCITAR.",
  "Mt 18,15-20": "JESUS: SE IRMÃO PECAR CONTRA VOCÊ / FALAR COM ELE A SÓS / SE OUVIR / VOCÊ GANHOU IRMÃO.\nSE NÃO OUVIR / LEVAR UMA OU DUAS PESSOAS.\nSE AINDA NÃO OUVIR / DIZER À COMUNIDADE.\nO QUE LIGAREM TERRA / LIGADO CÉU; DESLIGAREM / DESLIGADO.\nSE DOIS CONCORDAREM PEDIR / PAI ATENDER.\nONDE DOIS OU TRÊS REUNIDOS EM MEU NOME / EU ESTOU NO MEIO.",
  "Mt 18,21-35": "PEDRO: QUANTAS VEZES PERDOAR IRMÃO? ATÉ SETE?\nJESUS: NÃO SETE / MAS SEM LIMITAR.\nPARÁBOLA REI E SERVO DEVENDO ENORME DÍVIDA.\nSERVO PEDIR PACIÊNCIA / REI COMPAIXÃO / PERDOAR TUDO.\nMESMO SERVO ENCONTRAR COMPANHEIRO DEVENDO POUCO / AGARRAR / EXIGIR PAGAMENTO / MANDAR PRISÃO.\nREI SABER / CHAMAR SERVO MAU: EU PERDOEI VOCÊ / VOCÊ DEVIA TER COMPAIXÃO.\nJESUS: PAI ESPERA PERDÃO DE CORAÇÃO.",
  "Mt 2,1-12": "(CENÁRIO: magos Oriente → Jerusalém → Belém; Herodes; estrela)\nMAGOS CHEGAR JERUSALÉM / PERGUNTAR REI JUDEUS NASCEU ONDE? VIMOS ESTRELA / ADORAR.\nHERODES PERTURBADO / CONSULTAR ESCRITURAS / BELÉM.\nHERODES ENVIAR MAGOS / PEDIR NOTÍCIA.\nESTRELA GUIAR / PARAR SOBRE LUGAR MENINO.\nMAGOS ENTRAR / VER MENINO COM MARIA / PROSTRAR / ADORAR / OFERECER OURO / INCENSO / MIRRA.\nAVISADOS SONHO / VOLTAR OUTRO CAMINHO / NÃO HERODES.",
  "Mt 2,13-15.19-23": "(CENÁRIO: noite; anjo em sonho; fuga Egito → depois retorno → Nazaré)\nANJO DIZER JOSÉ: LEVANTA / PEGA MENINO E MÃE / FOGE EGITO / HERODES QUER MATAR.\nJOSÉ LEVANTAR NOITE / IR EGITO / FICAR ATÉ MORTE HERODES.\nDEPOIS ANJO: VOLTA TERRA ISRAEL / QUEM QUERIA MATAR MENINO MORREU.\nJOSÉ OUVIR FILHO HERODES GOVERNA JUDEIA / TER MEDO / AVISADO SONHO / IR GALILEIA.\nFAMÍLIA MORAR NAZARÉ.",
  "Mt 20,1-16": "(CENÁRIO: proprietário vinha contrata trabalhadores em vários horários)\nDONO SAIR CEDO / CONTRATAR POR UM DENÁRIO.\nSAIR OUTRAS HORAS / CONTRATAR MAIS / ATÉ FIM TARDE.\nNO FIM / PAGAR COMEÇANDO ÚLTIMOS / TODOS RECEBER UM DENÁRIO.\nPRIMEIROS RECLAMAR: TRABALHAMOS MAIS / VOCÊ IGUALOU.\nDONO: AMIGO / NÃO TE INJUSTICEI / COMBINAMOS UM DENÁRIO.\nEU POSSO SER GENEROSO COM O QUE É MEU.\nASSIM ÚLTIMOS PRIMEIROS / PRIMEIROS ÚLTIMOS.",
  "Mt 21,1-11": "(CENÁRIO: aproximação Jerusalém; jumenta/jumentinho; discípulos; multidão)\nJESUS ENVIAR DOIS DISCÍPULOS BUSCAR ANIMAIS / DIZER SENHOR PRECISA.\nCUMPRIR PROFECIA: REI HUMILDE VEM MONTADO.\nDISCÍPULOS COLOCAR MANTOS / JESUS MONTAR.\nMULTIDÃO ESTENDER MANTOS E RAMOS / ACLAMAR: HOSANA FILHO DAVI / BENDITO QUEM VEM NOME SENHOR.\nCIDADE AGITADA / PERGUNTAR QUEM É?\nMULTIDÃO: JESUS PROFETA DE NAZARÉ.",
  "Mt 21,28-32": "JESUS PARÁBOLA DOIS FILHOS.\nPAI DIZER PRIMEIRO: VAI TRABALHAR VINHA.\nELE: NÃO QUERO / DEPOIS MUDAR IDEIA / IR.\nSEGUNDO: SIM SENHOR / MAS NÃO IR.\nQUAL FEZ VONTADE PAI? PRIMEIRO.\nJESUS A LÍDERES: COBRADORES E PROSTITUTAS ENTRAM ANTES REINO / PORQUE CRERAM JOÃO.\nVOCÊS VIRAM / MAS NÃO MUDARAM PARA CRER.",
  "Mt 21,33-43": "(CENÁRIO: JESUS à frente; PRÍNCIPES-SACERDOTES/ANCIÃOS à direita; VINHA no centro; PROPRIETÁRIO à esquerda; VINHATEIROS dentro da VINHA)\n(MUDANÇA DE PAPEL: JESUS dirige-se aos líderes)\nOUTRA PARÁBOLA / VOCÊS ESCUTAR.\nHOMEM PROPRIETÁRIO / VINHA PLANTAR.\nAO-REDOR CERCA COLOCAR.\nDENTRO VINHA / LAGAR CAVAR / TORRE CONSTRUIR.\nDEPOIS VINHA ARRENDAR PARA VINHATEIROS / PROPRIETÁRIO VIAJAR LONGE.\n(TEMPO AVANÇA: COLHEITA CHEGAR)\nPROPRIETÁRIO SERVOS ENVIAR ATÉ VINHATEIROS / FRUTOS DELE RECEBER.\nVINHATEIROS SERVOS AGARRAR.\nUM SERVO BATER.\nOUTRO SERVO MATAR.\nOUTRO SERVO APEDREJAR.\nPROPRIETÁRIO OUTROS SERVOS ENVIAR / MAIS NUMEROSOS QUE PRIMEIROS.\nVINHATEIROS / MESMO JEITO MALTRATAR.\n(FOCO: FILHO/HERDEIRO)\nPOR-FIM PROPRIETÁRIO PRÓPRIO FILHO ENVIAR.\n(MUDANÇA DE PAPEL: pensamento do PROPRIETÁRIO)\nMEU FILHO / ELES VÃO RESPEITAR.\n(MUDANÇA DE PAPEL: VINHATEIROS conversam entre si)\nELES VER FILHO / DIZER: ELE HERDEIRO.\nVAMOS MATAR ELE / HERANÇA DELE FICAR NOSSA.\n(MOVIMENTO ESPACIAL: dentro da vinha → fora)\nELES FILHO AGARRAR / LEVAR-JOGAR FORA VINHA / MATAR.\n(RESET: voltar ao diálogo JESUS ↔ líderes)\nJESUS PERGUNTAR:\nDONO VINHA VOLTAR / AQUELES VINHATEIROS / ELE O-QUE FAZER?\n(MUDANÇA DE PAPEL: ouvintes respondem)\nAQUELES MALVADOS / DONO MATAR SEM PIEDADE.\nVINHA DEPOIS ARRENDAR PARA OUTROS VINHATEIROS.\nOUTROS VINHATEIROS / TEMPO CERTO / FRUTOS ENTREGAR AO DONO.\n(MUDANÇA DE PAPEL: JESUS)\nVOCÊS ESCRITURA JÁ-LER?\nPEDRA CONSTRUTORES REJEITAR / DEPOIS ESSA PEDRA TORNAR PEDRA-ANGULAR PRINCIPAL.\nISSO SENHOR FAZER / NOSSOS OLHOS VER / ADMIRÁVEL.\nPOR ISSO EU DIZER VOCÊS:\nREINO DEUS / DE VOCÊS TIRAR.\nREINO DEUS / DAR PARA OUTRO POVO / POVO PRODUZIR FRUTOS.\n(ENCERRAMENTO LITÚRGICO)\nPALAVRA SALVAÇÃO.",
  "Mt 22,1-14": "JESUS PARÁBOLA REI PREPARAR FESTA CASAMENTO FILHO.\nCONVIDADOS RECUSAR / ALGUNS IGNORAR / OUTROS MALTRATAR E MATAR SERVOS.\nREI JULGAR AGRESSORES.\nMANDAR SERVOS CRUZAMENTOS / CONVIDAR TODOS QUE ENCONTRAR / BONS E MAUS / SALÃO ENCHER.\nREI VER HOMEM SEM TRAJE FESTA / PERGUNTAR COMO ENTROU / ELE CALAR / SER RETIRADO.\nMUITOS CHAMADOS / POUCOS RESPONDEM ADEQUADAMENTE.",
  "Mt 22,15-21": "(CENÁRIO: fariseus planejam armadilha; discípulos deles + herodianos)\nPERGUNTAR JESUS: É PERMITIDO PAGAR IMPOSTO CÉSAR?\nJESUS SABER MALÍCIA / PEDIR MOEDA.\nPERGUNTAR IMAGEM E INSCRIÇÃO DE QUEM? CÉSAR.\nJESUS: DEVOLVER A CÉSAR O QUE É DE CÉSAR / E A DEUS O QUE É DE DEUS.",
  "Mt 22,34-40": "FARISEUS OUVIR JESUS CALAR SADUCEUS / DOUTOR LEI TESTAR: QUAL MAIOR MANDAMENTO?\nJESUS: AMAR SENHOR DEUS TODO CORAÇÃO / ALMA / MENTE.\nESSE PRIMEIRO E MAIOR.\nSEGUNDO SEMELHANTE: AMAR PRÓXIMO COMO A SI.\nTODA LEI E PROFETAS DEPENDEM DESTES DOIS.",
  "Mt 23,1-12": "JESUS FALAR MULTIDÃO E DISCÍPULOS SOBRE ESCRIBAS E FARISEUS.\nELES ENSINAM LEI / MAS NÃO PRATICAM / COLOCAM FARDOS NOS OUTROS / NÃO AJUDAM.\nFAZEM OBRAS PARA SER VISTOS / BUSCAM HONRA E TÍTULOS.\nVOCÊS NÃO BUSCAR SUPERIORIDADE / TODOS IRMÃOS / UM MESTRE CRISTO.\nMAIOR ENTRE VOCÊS / SER SERVO.\nQUEM SE EXALTA / SER HUMILHADO; QUEM SE HUMILHA / SER EXALTADO.",
  "Mt 24,37-44": "JESUS: COMO DIAS NOÉ / PESSOAS COMER / BEBER / CASAR / NÃO PERCEBER ATÉ DILÚVIO.\nASSIM SERÁ VINDA FILHO HOMEM.\nDOIS NO CAMPO / UM LEVADO / OUTRO FICA; DUAS MOENDO / UMA LEVADA / OUTRA FICA.\nVIGIAR / NÃO SABER DIA SENHOR.\nSE DONO CASA SOUBESSE HORA LADRÃO / FICARIA ALERTA.\nVOCÊS TAMBÉM PRONTOS / FILHO HOMEM VIRÁ QUANDO NÃO ESPERAM.",
  "Mt 25,1-13": "REINO CÉUS COMO DEZ VIRGENS COM LÂMPADAS ESPERAR NOIVO.\nCINCO PRUDENTES LEVAR ÓLEO / CINCO IMPREVIDENTES NÃO.\nNOIVO DEMORAR / TODAS DORMIR.\nMEIA-NOITE GRITO: NOIVO CHEGOU.\nIMPREVIDENTES PEDIR ÓLEO / PRUDENTES DIZER PODE FALTAR / VÃO COMPRAR.\nENQUANTO FORAM / NOIVO CHEGAR / PRONTAS ENTRAR FESTA / PORTA FECHAR.\nOUTRAS VOLTAR / PEDIR ABRIR / RESPOSTA: NÃO CONHEÇO VOCÊS.\nVIGIAR / NÃO SABER DIA NEM HORA.",
  "Mt 25,14-30": "HOMEM VIAJAR / ENTREGAR BENS SERVOS CONFORME CAPACIDADE: CINCO / DOIS / UM TALENTO.\nDOIS PRIMEIROS TRABALHAR / DOBRAR.\nTERCEIRO TER MEDO / ENTERRAR.\nSENHOR VOLTAR / PRESTAR CONTAS.\nPRIMEIROS: FIEL NO POUCO / ENTRAR ALEGRIA SENHOR.\nTERCEIRO DEVOLVER SÓ O QUE RECEBEU / ACUSAR SENHOR DURO.\nSENHOR: DEVIA AO MENOS FAZER RENDER / TALENTO TIRADO.\nQUEM USA O QUE RECEBE / CRESCER; QUEM ENTERRA / PERDER.",
  "Mt 25,31-46": "(CENÁRIO: Filho Homem em glória; nações reunidas; separar como pastor ovelhas e cabritos)\nREI DIZER AOS À DIREITA: VENHAM / RECEBAM REINO / EU TIVE FOME E DERAM COMER / SEDE E DERAM BEBER / ESTRANGEIRO ACOLHERAM / NU VESTIRAM / DOENTE E PRESO VISITARAM.\nELES: QUANDO FIZEMOS ISSO?\nREI: TUDO QUE FIZERAM A UM DOS MENORES / A MIM FIZERAM.\nAOS OUTROS: NÃO FIZERAM.\nELES TAMBÉM PERGUNTAR QUANDO.\nJESUS: O QUE NÃO FIZERAM A UM DOS MENORES / A MIM NÃO FIZERAM.\nJULGAMENTO MOSTRAR AMOR CONCRETO.",
  "Mt 26,14–27,66": "(CENÁRIO: traição → ceia → Getsêmani → prisão → julgamentos → cruz → sepulcro)\nJUDAS COMBINAR ENTREGAR JESUS.\nCEIA / JESUS PARTIR PÃO: CORPO / CÁLICE: SANGUE ALIANÇA / ANUNCIAR TRAIÇÃO.\nGETSÊMANI / JESUS ANGÚSTIA / ORAR: PAI, SE POSSÍVEL AFASTA CÁLICE / MAS TUA VONTADE.\nDISCÍPULOS DORMIR / JUDAS CHEGAR / JESUS PRESO.\nCONSELHO CONDENAR / PEDRO NEGAR TRÊS VEZES / CHORAR.\nJUDAS ARREPENDER / DEVOLVER DINHEIRO / MORRER.\nPILATOS INTERROGAR / MULTIDÃO ESCOLHER BARRABÁS / PEDIR CRUCIFICAÇÃO.\nSOLDADOS ZOMBAR / COROA ESPINHOS.\nJESUS CRUCIFICADO / SOFRER / MORRER / TERRA TREMER / CORTINA TEMPLO RASGAR.\nCENTURIÃO RECONHECER FILHO DE DEUS.\nJOSÉ ARIMATEIA SEPULTAR / GUARDA COLOCADA.",
  "Mt 28,16-20": "(CENÁRIO: monte Galileia; onze discípulos; JESUS)\nDISCÍPULOS VER JESUS / ADORAR / ALGUNS AINDA DUVIDAR.\nJESUS: TODA AUTORIDADE CÉU E TERRA FOI DADA A MIM.\nPORTANTO IR / FAZER DISCÍPULOS DE TODAS NAÇÕES / BATIZAR NOME PAI / FILHO / ESPÍRITO SANTO.\nENSINAR GUARDAR TUDO QUE MANDEI.\nEU ESTOU COM VOCÊS TODOS DIAS / ATÉ FIM.",
  "Mt 3,1-12": "(CENÁRIO: deserto Judeia; João; multidões; fariseus e saduceus)\nJOÃO PREGAR: CONVERTER / REINO CÉUS PRÓXIMO.\nVOZ DESERTO / PREPARAR CAMINHO SENHOR.\nPOVO CONFESSAR PECADOS / BATIZAR JORDÃO.\nJOÃO A LÍDERES: PRODUZIR FRUTO CONVERSÃO / NÃO CONFIAR SÓ DESCENDÊNCIA ABRAÃO.\nMACHADO NA RAIZ / ÁRVORE SEM FRUTO CORTADA.\nEU BATIZAR ÁGUA / VEM MAIS FORTE / ELE BATIZAR ESPÍRITO SANTO E FOGO.\nELE SEPARAR TRIGO E PALHA.",
  "Mt 3,13-17": "(CENÁRIO: Jordão; JESUS aproxima JOÃO)\nJESUS VIR GALILEIA PARA SER BATIZADO.\nJOÃO TENTAR IMPEDIR: EU PRECISO SER BATIZADO POR TI.\nJESUS: AGORA DEIXA / CONVÉM CUMPRIR TODA JUSTIÇA.\nJOÃO ACEITAR.\nJESUS SAIR ÁGUA / CÉU ABRIR / ESPÍRITO DEUS DESCER COMO POMBA / VOZ CÉU: ESTE MEU FILHO AMADO / NELE ME AGRADO.",
  "Mt 4,1-11": "(CENÁRIO: deserto; JESUS e tentador)\nESPÍRITO LEVAR JESUS DESERTO / QUARENTA DIAS JEJUAR / FOME.\nTENTADOR: SE FILHO DEUS / PEDRAS VIRAR PÃO.\nJESUS: HOMEM NÃO VIVE SÓ PÃO / MAS PALAVRA DEUS.\nTENTADOR LEVAR TEMPLO / PEDIR JOGAR-SE / CITAR ESCRITURA.\nJESUS: NÃO TENTAR SENHOR.\nLEVAR MONTE / OFERECER REINOS EM TROCA ADORAÇÃO.\nJESUS: AFASTA SATANÁS / ADORAR SÓ DEUS.\nDIABO IR / ANJOS SERVIR.",
  "Mt 4,12-23": "JESUS SABER JOÃO PRESO / IR GALILEIA / MORAR CAFARNAUM / CUMPRIR PROFECIA: POVO ESCURIDÃO VER GRANDE LUZ.\nJESUS COMEÇAR PREGAR: CONVERTER / REINO CÉUS PRÓXIMO.\nMAR GALILEIA / CHAMAR SIMÃO E ANDRÉ: VENHAM / FAREI PESCADORES DE PESSOAS.\nELES DEIXAR REDES.\nCHAMAR TIAGO E JOÃO / ELES DEIXAR BARCO E PAI.\nJESUS PERCORRER GALILEIA / ENSINAR / ANUNCIAR REINO / CURAR DOENÇAS.",
  "Mt 5,1-12": "(CENÁRIO: JESUS subir monte / sentar / discípulos aproximar / multidão ouvir)\nJESUS ENSINAR: FELIZES POBRES EM ESPÍRITO / REINO CÉUS.\nFELIZES QUEM CHORA / SER CONSOLADO.\nMANSOS / HERDAR TERRA.\nFOME E SEDE JUSTIÇA / SER SACIADOS.\nMISERICORDIOSOS / RECEBER MISERICÓRDIA.\nCORAÇÃO PURO / VER DEUS.\nPROMOVER PAZ / FILHOS DEUS.\nPERSEGUIDOS POR JUSTIÇA / REINO CÉUS.\nQUANDO INSULTADOS POR MINHA CAUSA / ALEGREM / RECOMPENSA CÉU.",
  "Mt 5,13-16": "JESUS: VOCÊS SAL DA TERRA.\nSE SAL PERDER SABOR / NÃO SERVIR.\nVOCÊS LUZ MUNDO.\nCIDADE NO MONTE NÃO ESCONDER.\nLÂMPADA NÃO COLOCAR DEBAIXO VASILHA / COLOCAR ALTO / ILUMINAR CASA.\nASSIM LUZ DE VOCÊS BRILHAR DIANTE PESSOAS / ELAS VER BOAS OBRAS / GLORIFICAR PAI CÉU.",
  "Mt 5,17-37": "JESUS: NÃO VIM ABOLIR LEI E PROFETAS / VIM CUMPRIR.\nJUSTIÇA DE VOCÊS PRECISA IR ALÉM APARÊNCIA.\nNÃO SÓ NÃO MATAR / TAMBÉM RECONCILIAR / NÃO ALIMENTAR IRA E DESPREZO.\nANTES OFERTA / SE IRMÃO TEM ALGO CONTRA VOCÊ / PRIMEIRO RECONCILIAR.\nNÃO SÓ ADULTÉRIO EXTERNO / TAMBÉM OLHAR COM DESEJO.\nFIDELIDADE NO MATRIMÔNIO / NÃO TRATAR ALIANÇA LEVEMENTE.\nNÃO USAR JURAMENTO PARA MANIPULAR VERDADE / SEU SIM SER SIM / NÃO SER NÃO.",
  "Mt 5,38-48": "JESUS: VOCÊS OUVIRAM OLHO POR OLHO.\nEU DIGO: NÃO RESPONDER MAL COM VINGANÇA.\nSE BATER FACE / NÃO ENTRAR CICLO VIOLÊNCIA.\nSE OBRIGAR UMA MILHA / IR DUAS.\nDAR A QUEM PEDIR.\nOUVIRAM AMAR PRÓXIMO / ODIAR INIMIGO.\nEU DIGO: AMAR INIMIGOS / ORAR QUEM PERSEGUE / ASSIM FILHOS PAI QUE FAZ SOL NASCER SOBRE BONS E MAUS.\nAMAR SÓ QUEM AMA VOCÊS / NADA EXTRAORDINÁRIO.\nSER PERFEITOS COMO PAI.",
  "Mt 6,24-34": "JESUS: NINGUÉM SERVIR DOIS SENHORES / NÃO PODE SERVIR DEUS E DINHEIRO.\nPOR ISSO NÃO VIVER DOMINADO PREOCUPAÇÃO COMIDA / BEBIDA / ROUPA.\nOLHAR AVES / PAI ALIMENTAR.\nOLHAR FLORES / DEUS VESTIR.\nSE DEUS CUIDA ASSIM / CUIDARÁ VOCÊS.\nNÃO FICAR ANSIOSOS COMO QUEM NÃO CONFIA.\nBUSCAR PRIMEIRO REINO DEUS E JUSTIÇA / NECESSÁRIO SERÁ DADO.\nNÃO PREOCUPAR AMANHÃ / CADA DIA TEM SEU DESAFIO.",
  "Mt 7,21-27": "JESUS: NÃO BASTA DIZER SENHOR, SENHOR / ENTRAR REINO QUEM FAZ VONTADE PAI.\nMUITOS DIZER FIZERAM COISAS EM MEU NOME / MAS EU DIRIA: NÃO CONHEÇO VOCÊS / AFASTEM-SE QUEM PRATICA MAL.\nQUEM OUVE MINHAS PALAVRAS E PRATICA / COMO HOMEM SÁBIO CONSTRUIR CASA SOBRE ROCHA.\nCHUVA / RIO / VENTO / CASA NÃO CAIR.\nQUEM OUVE E NÃO PRATICA / CASA SOBRE AREIA / CAIR GRANDE.",
  "Mt 9,36–10,8": "JESUS VER MULTIDÕES / COMPAIXÃO / CANSADAS E ABANDONADAS COMO OVELHAS SEM PASTOR.\nDIZER DISCÍPULOS: COLHEITA GRANDE / TRABALHADORES POUCOS / PEDIR SENHOR ENVIAR TRABALHADORES.\nCHAMAR DOZE / DAR AUTORIDADE CURAR E EXPULSAR ESPÍRITOS.\nENVIAR PRIMEIRO A ISRAEL / ANUNCIAR: REINO CÉUS PRÓXIMO.\nCURAR DOENTES / RESSUSCITAR MORTOS / PURIFICAR LEPROSOS / EXPULSAR DEMÔNIOS.\nVOCÊS RECEBERAM DE GRAÇA / DAR DE GRAÇA.",
  "Mt 9,9-13": "(CENÁRIO: coletoria → casa com cobradores e pecadores)\nJESUS VER MATEUS SENTADO COBRANDO IMPOSTOS / DIZER: SEGUE-ME.\nMATEUS LEVANTAR / SEGUIR.\nJESUS COMER COM COBRADORES E PECADORES.\nFARISEUS PERGUNTAR DISCÍPULOS: POR QUE MESTRE COME COM ELES?\nJESUS OUVIR: DOENTES PRECISAM MÉDICO / SADIOS NÃO.\nAPRENDER O QUE SIGNIFICA MISERICÓRDIA QUERO / NÃO SACRIFÍCIO.\nEU NÃO VIM CHAMAR JUSTOS / MAS PECADORES.",
  "Lc 1,1-4; 4,14-21": "(PRÓLOGO) MUITOS JÁ ESCREVERAM SOBRE ACONTECIMENTOS / EU INVESTIGAR TUDO DESDE INÍCIO COM CUIDADO / ORGANIZAR RELATO PARA TEÓFILO / PARA CONHECER FIRMEZA ENSINAMENTO.\n(CENÁRIO: Nazaré; sinagoga; JESUS lê o profeta Isaías)\nJESUS VOLTAR GALILEIA NO PODER ESPÍRITO / ENSINAR SINAGOGAS.\nEM NAZARÉ / LEVANTAR PARA LER / RECEBER ROLO ISAÍAS.\nLER: ESPÍRITO SENHOR SOBRE MIM / UNGIU PARA ANUNCIAR BOA NOTÍCIA POBRES / LIBERDADE PRESOS / VISTA CEGOS / LIBERTAR OPRIMIDOS / PROCLAMAR ANO GRAÇA SENHOR.\nFECHAR ROLO / SENTAR / TODOS OLHAR.\nJESUS: HOJE ESTA ESCRITURA SE CUMPRIU DIANTE DE VOCÊS."
});
